window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["HAB"]={"book":"HAB","editions":{"hbo-source":[[1,1,"הַ⁠מַּשָׂא֙ אֲשֶׁ֣ר חָזָ֔ה חֲבַקּ֖וּק הַ⁠נָּבִֽיא׃","ha⁠mȧşá̂ʼ֙ ʼàşě֣r ẖázá֔h ẖàbaq֖̇ẇq ha⁠ná̇biֽyʼ׃"],[1,2,"עַד־אָ֧נָה יְהוָ֛ה שִׁוַּ֖עְתִּי וְ⁠לֹ֣א תִשְׁמָ֑ע אֶזְעַ֥ק אֵלֶ֛י⁠ךָ חָמָ֖ס וְ⁠לֹ֥א תוֹשִֽׁיעַ׃","ʻad-ʼá֧náh yĕhwá֛h şǐwȧ֖ʻĕţi̇y wĕ⁠lò֣ʼ ţişĕ̌má֑ʻ ʼezĕʻa֥q ʼéle֛y⁠ká ẖámá֖s wĕ⁠lò֥ʼ ţwòşǐֽyʻa׃"],[1,3,"לָ֣⁠מָּה תַרְאֵ֤⁠נִי אָ֨וֶן֙ וְ⁠עָמָ֣ל תַּבִּ֔יט וְ⁠שֹׁ֥ד וְ⁠חָמָ֖ס לְ⁠נֶגְדִּ֑⁠י וַ⁠יְהִ֧י רִ֦יב וּ⁠מָד֖וֹן יִשָּֽׂא׃","lá֣⁠má̇h ţarĕʼé֤⁠niy ʼá֨wen֙ wĕ⁠ʻámá֣l ţȧbi̇֔yt wĕ⁠şò֥̌d wĕ⁠ẖámá֖s lĕ⁠negĕdi֑̇⁠y wa⁠yĕhi֧y ri֦yb ẇ⁠mád֖wòn yişáֽ̇̂ʼ׃"],[1,4,"עַל־כֵּן֙ תָּפ֣וּג תּוֹרָ֔ה וְ⁠לֹֽא־יֵצֵ֥א לָ⁠נֶ֖צַח מִשְׁפָּ֑ט כִּ֤י רָשָׁע֙ מַכְתִּ֣יר אֶת־הַ⁠צַּדִּ֔יק עַל־כֵּ֛ן יֵצֵ֥א מִשְׁפָּ֖ט מְעֻקָּֽל׃","ʻal-ké̇n֙ ţá̇p֣ẇg ţ̇wòrá֔h wĕ⁠lòֽʼ-yéẕé֥ʼ lá⁠ne֖ẕaẖ mişĕ̌pá֑̇t ki֤̇y ráşá̌ʻ֙ makĕţi֣̇yr ʼeţ-ha⁠ẕȧdi̇֔yq ʻal-ké֛̇n yéẕé֥ʼ mişĕ̌pá֖̇t mĕʻuqáֽ̇l׃"],[1,5,"רְא֤וּ בַ⁠גּוֹיִם֙ וְֽ⁠הַבִּ֔יטוּ וְ⁠הִֽתַּמְּה֖וּ תְּמָ֑הוּ כִּי־פֹ֨עַל֙ פֹּעֵ֣ל בִּֽ⁠ימֵי⁠כֶ֔ם לֹ֥א תַאֲמִ֖ינוּ כִּ֥י יְסֻפָּֽר׃","rĕʼ֤ẇ ba⁠ġwòyim֙ wĕֽ⁠habi̇֔ytẇ wĕ⁠hiֽţȧmĕ̇h֖ẇ ţĕ̇má֑hẇ ki̇y-pò֨ʻal֙ pò̇ʻé֣l biֽ̇⁠yméy⁠ke֔m lò֥ʼ ţaʼàmi֖ynẇ ki֥̇y yĕsupáֽ̇r׃"],[1,6,"כִּֽי־הִנְ⁠נִ֤י מֵקִים֙ אֶת־הַ⁠כַּשְׂדִּ֔ים הַ⁠גּ֖וֹי הַ⁠מַּ֣ר וְ⁠הַ⁠נִּמְהָ֑ר הַֽ⁠הוֹלֵךְ֙ לְ⁠מֶרְחֲבֵי־אֶ֔רֶץ לָ⁠רֶ֖שֶׁת מִשְׁכָּנ֥וֹת לֹּא־לֽ⁠וֹ׃","kiֽ̇y-hinĕ⁠ni֤y méqiym֙ ʼeţ-ha⁠kȧşĕ̂di̇֔ym ha⁠ġ֖wòy ha⁠mȧ֣r wĕ⁠ha⁠ni̇mĕhá֑r haֽ⁠hwòlékĕ֙ lĕ⁠merĕẖàbéy-ʼe֔reẕ lá⁠re֖şěţ mişĕ̌ká̇n֥wòţ lò̇ʼ-lֽ⁠wò׃"],[1,7,"אָיֹ֥ם וְ⁠נוֹרָ֖א ה֑וּא מִמֶּ֕⁠נּוּ מִשְׁפָּט֥⁠וֹ וּ⁠שְׂאֵת֖⁠וֹ יֵצֵֽא׃","ʼáyò֥m wĕ⁠nwòrá֖ʼ h֑ẇʼ mimė֕⁠ṅẇ mişĕ̌pá̇t֥⁠wò ẇ⁠şĕ̂ʼéţ֖⁠wò yéẕéֽʼ׃"],[1,8,"וְ⁠קַלּ֨וּ מִ⁠נְּמֵרִ֜ים סוּסָ֗י⁠ו וְ⁠חַדּוּ֙ מִ⁠זְּאֵ֣בֵי עֶ֔רֶב וּ⁠פָ֖שׁוּ פָּֽרָשָׁ֑י⁠ו וּ⁠פָֽרָשָׁי⁠ו֙ מֵ⁠רָח֣וֹק יָבֹ֔אוּ יָעֻ֕פוּ כְּ⁠נֶ֖שֶׁר חָ֥שׁ לֶ⁠אֱכֽוֹל׃","wĕ⁠qal̇֨ẇ mi⁠nĕ̇méri֜ym sẇsá֗y⁠w wĕ⁠ẖaḋẇ֙ mi⁠zĕ̇ʼé֣béy ʻe֔reb ẇ⁠pá֖ş̌ẇ páֽ̇ráşá֑̌y⁠w ẇ⁠páֽráşá̌y⁠w֙ mé⁠ráẖ֣wòq yábò֔ʼẇ yáʻu֕pẇ kĕ̇⁠ne֖şěr ẖá֥ş̌ le⁠ʼèkֽwòl׃"],[1,9,"כֻּלֹּ⁠ה֙ לְ⁠חָמָ֣ס יָב֔וֹא מְגַמַּ֥ת פְּנֵי⁠הֶ֖ם קָדִ֑ימָ⁠ה וַ⁠יֶּאֱסֹ֥ף כַּ⁠ח֖וֹל שֶֽׁבִי׃","ku̇lò̇⁠h֙ lĕ⁠ẖámá֣s yáb֔wòʼ mĕgamȧ֥ţ pĕ̇néy⁠he֖m qádi֑ymá⁠h wa⁠yėʼèsò֥p kȧ⁠ẖ֖wòl şěֽbiy׃"],[1,10,"וְ⁠הוּא֙ בַּ⁠מְּלָכִ֣ים יִתְקַלָּ֔ס וְ⁠רֹזְנִ֖ים מִשְׂחָ֣ק ל֑⁠וֹ ה֚וּא לְ⁠כָל־מִבְצָ֣ר יִשְׂחָ֔ק וַ⁠יִּצְבֹּ֥ר עָפָ֖ר וַֽ⁠יִּלְכְּדָֽ⁠הּ׃","wĕ⁠hẇʼ֙ bȧ⁠mĕ̇láki֣ym yiţĕqalá̇֔s wĕ⁠ròzĕni֖ym mişĕ̂ẖá֣q l֑⁠wò h֚ẇʼ lĕ⁠kál-mibĕẕá֣r yişĕ̂ẖá֔q wa⁠yi̇ẕĕbò֥̇r ʻápá֖r waֽ⁠yi̇lĕkĕ̇dáֽ⁠ḣ׃"],[1,11,"אָ֣ז חָלַ֥ף ר֛וּחַ וַֽ⁠יַּעֲבֹ֖ר וְ⁠אָשֵׁ֑ם ז֥וּ כֹח֖⁠וֹ לֵ⁠אלֹהֽ⁠וֹ׃","ʼá֣z ẖála֥p r֛ẇẖa waֽ⁠yȧʻàbò֖r wĕ⁠ʼáşé֑̌m z֥ẇ kòẖ֖⁠wò lé⁠ʼlòhֽ⁠wò׃"],[1,12,"הֲ⁠ל֧וֹא אַתָּ֣ה מִ⁠קֶּ֗דֶם יְהוָ֧ה אֱלֹהַ֛⁠י קְדֹשִׁ֖⁠י לֹ֣א נָמ֑וּת יְהוָה֙ לְ⁠מִשְׁפָּ֣ט שַׂמְתּ֔⁠וֹ וְ⁠צ֖וּר לְ⁠הוֹכִ֥יחַ יְסַדְתּֽ⁠וֹ׃","hà⁠l֧wòʼ ʼaţá֣̇h mi⁠qė֗dem yĕhwá֧h ʼèlòha֛⁠y qĕdòşǐ֖⁠y lò֣ʼ nám֑ẇţ yĕhwáh֙ lĕ⁠mişĕ̌pá֣̇t şâmĕţ̇֔⁠wò wĕ⁠ẕ֖ẇr lĕ⁠hwòki֥yẖa yĕsadĕţֽ̇⁠wò׃"],[1,13,"טְה֤וֹר עֵינַ֨יִם֙ מֵ⁠רְא֣וֹת רָ֔ע וְ⁠הַבִּ֥יט אֶל־עָמָ֖ל לֹ֣א תוּכָ֑ל לָ֤⁠מָּה תַבִּיט֙ בּֽוֹגְדִ֔ים תַּחֲרִ֕ישׁ בְּ⁠בַלַּ֥ע רָשָׁ֖ע צַדִּ֥יק מִמֶּֽ⁠נּוּ׃","tĕh֤wòr ʻéyna֨yim֙ mé⁠rĕʼ֣wòţ rá֔ʻ wĕ⁠habi֥̇yt ʼel-ʻámá֖l lò֣ʼ ţẇká֑l lá֤⁠má̇h ţabi̇yt֙ ḃֽwògĕdi֔ym ţȧẖàri֕yş̌ bĕ̇⁠balȧ֥ʻ ráşá֖̌ʻ ẕadi֥̇yq mimėֽ⁠ṅẇ׃"],[1,14,"וַ⁠תַּעֲשֶׂ֥ה אָדָ֖ם כִּ⁠דְגֵ֣י הַ⁠יָּ֑ם כְּ⁠רֶ֖מֶשׂ לֹא־מֹשֵׁ֥ל בּֽ⁠וֹ׃","wa⁠ţȧʻàşê֥h ʼádá֖m ki̇⁠dĕgé֣y ha⁠yá֑̇m kĕ̇⁠re֖meş̂ lòʼ-mòşé֥̌l ḃֽ⁠wò׃"],[1,15,"כֻּלֹּ⁠ה֙ בְּ⁠חַכָּ֣ה הֵֽעֲלָ֔ה יְגֹרֵ֣⁠הוּ בְ⁠חֶרְמ֔⁠וֹ וְ⁠יַאַסְפֵ֖⁠הוּ בְּ⁠מִכְמַרְתּ֑⁠וֹ עַל־כֵּ֖ן יִשְׂמַ֥ח וְ⁠יָגִֽיל׃","ku̇lò̇⁠h֙ bĕ̇⁠ẖaká֣̇h héֽʻàlá֔h yĕgòré֣⁠hẇ bĕ⁠ẖerĕm֔⁠wò wĕ⁠yaʼasĕpé֖⁠hẇ bĕ̇⁠mikĕmarĕţ֑̇⁠wò ʻal-ké֖̇n yişĕ̂ma֥ẖ wĕ⁠yágiֽyl׃"],[1,16,"עַל־כֵּן֙ יְזַבֵּ֣חַ לְ⁠חֶרְמ֔⁠וֹ וִֽ⁠יקַטֵּ֖ר לְ⁠מִכְמַרְתּ֑⁠וֹ כִּ֤י בָ⁠הֵ֨מָּה֙ שָׁמֵ֣ן חֶלְק֔⁠וֹ וּ⁠מַאֲכָל֖⁠וֹ בְּרִאָֽה׃","ʻal-ké̇n֙ yĕzabé֣̇ẖa lĕ⁠ẖerĕm֔⁠wò wiֽ⁠yqaté֖̇r lĕ⁠mikĕmarĕţ֑̇⁠wò ki֤̇y bá⁠hé֨má̇h֙ şá̌mé֣n ẖelĕq֔⁠wò ẇ⁠maʼàkál֖⁠wò bĕ̇riʼáֽh׃"],[1,17,"הַ֥⁠עַל כֵּ֖ן יָרִ֣יק חֶרְמ֑⁠וֹ וְ⁠תָמִ֛יד לַ⁠הֲרֹ֥ג גּוֹיִ֖ם לֹ֥א יַחְמֽוֹל׃ס","ha֥⁠ʻal ké֖̇n yári֣yq ẖerĕm֑⁠wò wĕ⁠ţámi֛yd la⁠hàrò֥g ġwòyi֖m lò֥ʼ yaẖĕmֽwòl׃s"],[2,1,"עַל־מִשְׁמַרְתִּ֣⁠י אֶעֱמֹ֔דָה וְ⁠אֶֽתְיַצְּבָ֖ה עַל־מָצ֑וֹר וַ⁠אֲצַפֶּ֗ה לִ⁠רְאוֹת֙ מַה־יְדַבֶּר־בִּ֔⁠י וּ⁠מָ֥ה אָשִׁ֖יב עַל־תּוֹכַחְתִּֽ⁠י׃","ʻal-mişĕ̌marĕţi֣̇⁠y ʼeʻèmò֔dáh wĕ⁠ʼeֽţĕyaẕĕ̇bá֖h ʻal-máẕ֑wòr wa⁠ʼàẕapė֗h li⁠rĕʼwòţ֙ mah-yĕdabėr-bi̇֔⁠y ẇ⁠má֥h ʼáşǐ֖yb ʻal-ţ̇wòkaẖĕţiֽ̇⁠y׃"],[2,2,"וַ⁠יַּעֲנֵ֤⁠נִי יְהוָה֙ וַ⁠יֹּ֔אמֶר כְּת֣וֹב חָז֔וֹן וּ⁠בָאֵ֖ר עַל־הַ⁠לֻּח֑וֹת לְמַ֥עַן יָר֖וּץ ק֥וֹרֵא בֽ⁠וֹ׃","wa⁠yȧʻàné֤⁠niy yĕhwáh֙ wa⁠yò̇֔ʼmer kĕ̇ţ֣wòb ẖáz֔wòn ẇ⁠báʼé֖r ʻal-ha⁠lu̇ẖ֑wòţ lĕma֥ʻan yár֖ẇẕ q֥wòréʼ bֽ⁠wò׃"],[2,3,"כִּ֣י ע֤וֹד חָזוֹן֙ לַ⁠מּוֹעֵ֔ד וְ⁠יָפֵ֥חַ לַ⁠קֵּ֖ץ וְ⁠לֹ֣א יְכַזֵּ֑ב אִם־יִתְמַהְמָהּ֙ חַכֵּה־ל֔⁠וֹ כִּֽי־בֹ֥א יָבֹ֖א לֹ֥א יְאַחֵֽר׃","ki֣̇y ʻ֤wòd ẖázwòn֙ la⁠ṁwòʻé֔d wĕ⁠yápé֥ẖa la⁠qé֖̇ẕ wĕ⁠lò֣ʼ yĕkazé֑̇b ʼim-yiţĕmahĕmáḣ֙ ẖaké̇h-l֔⁠wò kiֽ̇y-bò֥ʼ yábò֖ʼ lò֥ʼ yĕʼaẖéֽr׃"],[2,4,"הִנֵּ֣ה עֻפְּלָ֔ה לֹא־יָשְׁרָ֥ה נַפְשׁ֖⁠וֹ בּ֑⁠וֹ וְ⁠צַדִּ֖יק בֶּ⁠אֱמוּנָת֥⁠וֹ יִחְיֶֽה׃","hiné֣̇h ʻupĕ̇lá֔h lòʼ-yáşĕ̌rá֥h napĕş֖̌⁠wò ḃ֑⁠wò wĕ⁠ẕadi֖̇yq bė⁠ʼèmẇnáţ֥⁠wò yiẖĕyeֽh׃"],[2,5,"וְ⁠אַף֙ כִּֽי־הַ⁠יַּ֣יִן בּוֹגֵ֔ד גֶּ֥בֶר יָהִ֖יר וְ⁠לֹ֣א יִנְוֶ֑ה אֲשֶׁר֩ הִרְחִ֨יב כִּ⁠שְׁא֜וֹל נַפְשׁ֗⁠וֹ וְ⁠ה֤וּא כַ⁠מָּ֨וֶת֙ וְ⁠לֹ֣א יִשְׂבָּ֔ע וַ⁠יֶּאֱסֹ֤ף אֵלָי⁠ו֙ כָּל־הַ⁠גּוֹיִ֔ם וַ⁠יִּקְבֹּ֥ץ אֵלָ֖י⁠ו כָּל־הָ⁠עַמִּֽים׃","wĕ⁠ʼap֙ kiֽ̇y-ha⁠yȧ֣yin ḃwògé֔d gė֥ber yáhi֖yr wĕ⁠lò֣ʼ yinĕwe֑h ʼàşěr֩ hirĕẖi֨yb ki̇⁠şĕ̌ʼ֜wòl napĕş̌֗⁠wò wĕ⁠h֤ẇʼ ka⁠má̇֨weţ֙ wĕ⁠lò֣ʼ yişĕ̂bá̇֔ʻ wa⁠yėʼèsò֤p ʼéláy⁠w֙ ká̇l-ha⁠ġwòyi֔m wa⁠yi̇qĕbò֥̇ẕ ʼélá֖y⁠w ká̇l-há⁠ʻamiֽ̇ym׃"],[2,6,"הֲ⁠לוֹא־אֵ֣לֶּה כֻלָּ֗⁠ם עָלָי⁠ו֙ מָשָׁ֣ל יִשָּׂ֔אוּ וּ⁠מְלִיצָ֖ה חִיד֣וֹת ל֑⁠וֹ וְ⁠יֹאמַ֗ר ה֚וֹי הַ⁠מַּרְבֶּ֣ה לֹּא־ל֔⁠וֹ עַד־מָתַ֕י וּ⁠מַכְבִּ֥יד עָלָ֖י⁠ו עַבְטִֽיט׃","hà⁠lwòʼ-ʼé֣lėh kulá̇֗⁠m ʻáláy⁠w֙ máşá֣̌l yişá̇̂֔ʼẇ ẇ⁠mĕliyẕá֖h ẖiyd֣wòţ l֑⁠wò wĕ⁠yòʼma֗r h֚wòy ha⁠mȧrĕbė֣h lò̇ʼ-l֔⁠wò ʻad-máţa֕y ẇ⁠makĕbi֥̇yd ʻálá֖y⁠w ʻabĕtiֽyt׃"],[2,7,"הֲ⁠ל֣וֹא פֶ֗תַע יָק֨וּמוּ֙ נֹשְׁכֶ֔י⁠ךָ וְ⁠יִקְצ֖וּ מְזַעְזְעֶ֑י⁠ךָ וְ⁠הָיִ֥יתָ לִ⁠מְשִׁסּ֖וֹת לָֽ⁠מוֹ׃","hà⁠l֣wòʼ pe֗ţaʻ yáq֨ẇmẇ֙ nòşĕ̌ke֔y⁠ká wĕ⁠yiqĕẕ֖ẇ mĕzaʻĕzĕʻe֑y⁠ká wĕ⁠háyi֥yţá li⁠mĕşǐṡ֖wòţ láֽ⁠mwò׃"],[2,8,"כִּֽי אַתָּ֤ה שַׁלּ֨וֹתָ֙ גּוֹיִ֣ם רַבִּ֔ים יְשָׁלּ֖וּ⁠ךָ כָּל־יֶ֣תֶר עַמִּ֑ים מִ⁠דְּמֵ֤י אָדָם֙ וַ⁠חֲמַס־אֶ֔רֶץ קִרְיָ֖ה וְ⁠כָל־יֹ֥שְׁבֵי בָֽ⁠הּ׃פ","kiֽ̇y ʼaţá֤̇h şǎl̇֨wòţá֙ ġwòyi֣m rabi̇֔ym yĕşá̌l֖̇ẇ⁠ká ká̇l-ye֣ţer ʻami֑̇ym mi⁠dĕ̇mé֤y ʼádám֙ wa⁠ẖàmas-ʼe֔reẕ qirĕyá֖h wĕ⁠kál-yò֥şĕ̌béy báֽ⁠ḣ׃p"],[2,9,"ה֗וֹי בֹּצֵ֛עַ בֶּ֥צַע רָ֖ע לְ⁠בֵית֑⁠וֹ לָ⁠שׂ֤וּם בַּ⁠מָּרוֹם֙ קִנּ֔⁠וֹ לְ⁠הִנָּצֵ֖ל מִ⁠כַּף־רָֽע׃","h֗wòy bò̇ẕé֛ʻa bė֥ẕaʻ rá֖ʻ lĕ⁠béyţ֑⁠wò lá⁠ş֤̂ẇm bȧ⁠má̇rwòm֙ qiṅ֔⁠wò lĕ⁠hiná̇ẕé֖l mi⁠kȧp-ráֽʻ׃"],[2,10,"יָעַ֥צְתָּ בֹּ֖שֶׁת לְ⁠בֵיתֶ֑⁠ךָ קְצוֹת־עַמִּ֥ים רַבִּ֖ים וְ⁠חוֹטֵ֥א נַפְשֶֽׁ⁠ךָ׃","yáʻa֥ẕĕţá̇ bò֖̇şěţ lĕ⁠béyţe֑⁠ká qĕẕwòţ-ʻami֥̇ym rabi֖̇ym wĕ⁠ẖwòté֥ʼ napĕşěֽ⁠ká׃"],[2,11,"כִּי־אֶ֖בֶן מִ⁠קִּ֣יר תִּזְעָ֑ק וְ⁠כָפִ֖יס מֵ⁠עֵ֥ץ יַעֲנֶֽ⁠נָּה׃פ","ki̇y-ʼe֖ben mi⁠qi֣̇yr ţi̇zĕʻá֑q wĕ⁠kápi֖ys mé⁠ʻé֥ẕ yaʻàneֽ⁠ná̇h׃p"],[2,12,"ה֛וֹי בֹּנֶ֥ה עִ֖יר בְּ⁠דָמִ֑ים וְ⁠כוֹנֵ֥ן קִרְיָ֖ה בְּ⁠עַוְלָֽה׃","h֛wòy bò̇ne֥h ʻi֖yr bĕ̇⁠dámi֑ym wĕ⁠kwòné֥n qirĕyá֖h bĕ̇⁠ʻawĕláֽh׃"],[2,13,"הֲ⁠ל֣וֹא הִנֵּ֔ה מֵ⁠אֵ֖ת יְהוָ֣ה צְבָא֑וֹת וְ⁠יִֽיגְע֤וּ עַמִּים֙ בְּ⁠דֵי־אֵ֔שׁ וּ⁠לְאֻמִּ֖ים בְּ⁠דֵי־רִ֥יק יִעָֽפוּ׃","hà⁠l֣wòʼ hiné̇֔h mé⁠ʼé֖ţ yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠yiֽygĕʻ֤ẇ ʻami̇ym֙ bĕ̇⁠déy-ʼé֔ş̌ ẇ⁠lĕʼumi֖̇ym bĕ̇⁠déy-ri֥yq yiʻáֽpẇ׃"],[2,14,"כִּ֚י תִּמָּלֵ֣א הָ⁠אָ֔רֶץ לָ⁠דַ֖עַת אֶת־כְּב֣וֹד יְהוָ֑ה כַּ⁠מַּ֖יִם יְכַסּ֥וּ עַל־יָֽם׃ס","ki֚̇y ţi̇má̇lé֣ʼ há⁠ʼá֔reẕ lá⁠da֖ʻaţ ʼeţ-kĕ̇b֣wòd yĕhwá֑h kȧ⁠mȧ֖yim yĕkaṡ֥ẇ ʻal-yáֽm׃s"],[2,15,"ה֚וֹי מַשְׁקֵ֣ה רֵעֵ֔⁠הוּ מְסַפֵּ֥חַ חֲמָתְ⁠ךָ֖ וְ⁠אַ֣ף שַׁכֵּ֑ר לְמַ֥עַן הַבִּ֖יט עַל־מְעוֹרֵי⁠הֶֽם׃","h֚wòy maşĕ̌qé֣h réʻé֔⁠hẇ mĕsapé֥̇ẖa ẖàmáţĕ⁠ká֖ wĕ⁠ʼa֣p şǎké֑̇r lĕma֥ʻan habi֖̇yt ʻal-mĕʻwòréy⁠heֽm׃"],[2,16,"שָׂבַ֤עְתָּ קָלוֹן֙ מִ⁠כָּב֔וֹד שְׁתֵ֥ה גַם־אַ֖תָּה וְ⁠הֵֽעָרֵ֑ל תִּסּ֣וֹב עָלֶ֗י⁠ךָ כּ֚וֹס יְמִ֣ין יְהוָ֔ה וְ⁠קִיקָל֖וֹן עַל־כְּבוֹדֶֽ⁠ךָ׃","şá̂ba֤ʻĕţá̇ qálwòn֙ mi⁠ká̇b֔wòd şĕ̌ţé֥h gam-ʼa֖ţá̇h wĕ⁠héֽʻáré֑l ţi̇ṡ֣wòb ʻále֗y⁠ká k֚̇wòs yĕmi֣yn yĕhwá֔h wĕ⁠qiyqál֖wòn ʻal-kĕ̇bwòdeֽ⁠ká׃"],[2,17,"כִּ֣י חֲמַ֤ס לְבָנוֹן֙ יְכַסֶּ֔⁠ךָּ וְ⁠שֹׁ֥ד בְּהֵמ֖וֹת יְחִיתַ֑⁠ן מִ⁠דְּמֵ֤י אָדָם֙ וַ⁠חֲמַס־אֶ֔רֶץ קִרְיָ֖ה וְ⁠כָל־יֹ֥שְׁבֵי בָֽ⁠הּ׃ס","ki֣̇y ẖàma֤s lĕbánwòn֙ yĕkasė֔⁠ká̇ wĕ⁠şò֥̌d bĕ̇hém֖wòţ yĕẖiyţa֑⁠n mi⁠dĕ̇mé֤y ʼádám֙ wa⁠ẖàmas-ʼe֔reẕ qirĕyá֖h wĕ⁠kál-yò֥şĕ̌béy báֽ⁠ḣ׃s"],[2,18,"מָֽה־הוֹעִ֣יל פֶּ֗סֶל כִּ֤י פְסָל⁠וֹ֙ יֹֽצְר֔⁠וֹ מַסֵּכָ֖ה וּ⁠מ֣וֹרֶה שָּׁ֑קֶר כִּ֣י בָטַ֞ח יֹצֵ֤ר יִצְר⁠וֹ֙ עָלָ֔י⁠ו לַ⁠עֲשׂ֖וֹת אֱלִילִ֥ים אִלְּמִֽים׃ס","máֽh-hwòʻi֣yl pė֗sel ki֤̇y pĕsál⁠wò֙ yòֽẕĕr֔⁠wò masé̇ká֖h ẇ⁠m֣wòreh şá֑̇̌qer ki֣̇y báta֞ẖ yòẕé֤r yiẕĕr⁠wò֙ ʻálá֔y⁠w la⁠ʻàş֖̂wòţ ʼèliyli֥ym ʼilĕ̇miֽym׃s"],[2,19,"ה֣וֹי אֹמֵ֤ר לָ⁠עֵץ֙ הָקִ֔יצָ⁠ה ע֖וּרִי לְ⁠אֶ֣בֶן דּוּמָ֑ם ה֣וּא יוֹרֶ֔ה הִנֵּה־ה֗וּא תָּפוּשׂ֙ זָהָ֣ב וָ⁠כֶ֔סֶף וְ⁠כָל־ר֖וּחַ אֵ֥ין בְּ⁠קִרְבּֽ⁠וֹ׃","h֣wòy ʼòmé֤r lá⁠ʻéẕ֙ háqi֔yẕá⁠h ʻ֖ẇriy lĕ⁠ʼe֣ben ḋẇmá֑m h֣ẇʼ ywòre֔h hiné̇h-h֗ẇʼ ţá̇pẇş̂֙ záhá֣b wá⁠ke֔sep wĕ⁠kál-r֖ẇẖa ʼé֥yn bĕ̇⁠qirĕḃֽ⁠wò׃"],[2,20,"וַֽ⁠יהוָ֖ה בְּ⁠הֵיכַ֣ל קָדְשׁ֑⁠וֹ הַ֥ס מִ⁠פָּנָ֖י⁠ו כָּל־הָ⁠אָֽרֶץ׃פ","waֽ⁠yhwá֖h bĕ̇⁠héyka֣l qádĕş֑̌⁠wò ha֥s mi⁠pá̇ná֖y⁠w ká̇l-há⁠ʼáֽreẕ׃p"],[3,1,"תְּפִלָּ֖ה לַ⁠חֲבַקּ֣וּק הַ⁠נָּבִ֑יא עַ֖ל שִׁגְיֹנֽוֹת׃","ţĕ̇pilá֖̇h la⁠ẖàbaq֣̇ẇq ha⁠ná̇bi֑yʼ ʻa֖l şǐgĕyònֽwòţ׃"],[3,2,"יְהוָ֗ה שָׁמַ֣עְתִּי שִׁמְעֲ⁠ךָ֮ יָרֵאתִי֒ יְהוָ֗ה פָּֽעָלְ⁠ךָ֙ בְּ⁠קֶ֤רֶב שָׁנִים֙ חַיֵּ֔י⁠הוּ בְּ⁠קֶ֥רֶב שָׁנִ֖ים תּוֹדִ֑יעַ בְּ⁠רֹ֖גֶז רַחֵ֥ם תִּזְכּֽוֹר׃","yĕhwá֗h şá̌ma֣ʻĕţi̇y şǐmĕʻà⁠ká֮ yáréʼţiy֒ yĕhwá֗h páֽ̇ʻálĕ⁠ká֙ bĕ̇⁠qe֤reb şá̌niym֙ ẖayé̇֔y⁠hẇ bĕ̇⁠qe֥reb şá̌ni֖ym ţ̇wòdi֑yʻa bĕ̇⁠rò֖gez raẖé֥m ţi̇zĕkֽ̇wòr׃"],[3,3,"אֱל֨וֹהַ֙ מִ⁠תֵּימָ֣ן יָב֔וֹא וְ⁠קָד֥וֹשׁ מֵֽ⁠הַר־פָּארָ֖ן סֶ֑לָה כִּסָּ֤ה שָׁמַ֨יִם֙ הוֹד֔⁠וֹ וּ⁠תְהִלָּת֖⁠וֹ מָלְאָ֥ה הָ⁠אָֽרֶץ׃","ʼèl֨wòha֙ mi⁠ţé̇ymá֣n yáb֔wòʼ wĕ⁠qád֥wòş̌ méֽ⁠har-pá̇ʼrá֖n se֑láh ki̇sá֤̇h şá̌ma֨yim֙ hwòd֔⁠wò ẇ⁠ţĕhilá̇ţ֖⁠wò málĕʼá֥h há⁠ʼáֽreẕ׃"],[3,4,"וְ⁠נֹ֨גַהּ֙ כָּ⁠א֣וֹר תִּֽהְיֶ֔ה קַרְנַ֥יִם מִ⁠יָּד֖⁠וֹ ל֑⁠וֹ וְ⁠שָׁ֖ם חֶבְי֥וֹן עֻזֹּֽ⁠ה׃","wĕ⁠nò֨gaḣ֙ ká̇⁠ʼ֣wòr ţiֽ̇hĕye֔h qarĕna֥yim mi⁠yá̇d֖⁠wò l֑⁠wò wĕ⁠şá֖̌m ẖebĕy֥wòn ʻuzòֽ̇⁠h׃"],[3,5,"לְ⁠פָנָ֖י⁠ו יֵ֣לֶךְ דָּ֑בֶר וְ⁠יֵצֵ֥א רֶ֖שֶׁף לְ⁠רַגְלָֽי⁠ו׃","lĕ⁠páná֖y⁠w yé֣lekĕ dá֑̇ber wĕ⁠yéẕé֥ʼ re֖şěp lĕ⁠ragĕláֽy⁠w׃"],[3,6,"עָמַ֣ד ׀ וַ⁠יְמֹ֣דֶד אֶ֗רֶץ רָאָה֙ וַ⁠יַּתֵּ֣ר גּוֹיִ֔ם וַ⁠יִּתְפֹּֽצְצוּ֙ הַרְרֵי־עַ֔ד שַׁח֖וּ גִּבְע֣וֹת עוֹלָ֑ם הֲלִיכ֥וֹת עוֹלָ֖ם לֽ⁠וֹ׃","ʻáma֣d ׀ wa⁠yĕmò֣ded ʼe֗reẕ ráʼáh֙ wa⁠yȧţé֣̇r ġwòyi֔m wa⁠yi̇ţĕpòֽ̇ẕĕẕẇ֙ harĕréy-ʻa֔d şǎẖ֖ẇ gi̇bĕʻ֣wòţ ʻwòlá֑m hàliyk֥wòţ ʻwòlá֖m lֽ⁠wò׃"],[3,7,"תַּ֣חַת אָ֔וֶן רָאִ֖יתִי אָהֳלֵ֣י כוּשָׁ֑ן יִרְגְּז֕וּ⁠ן יְרִיע֖וֹת אֶ֥רֶץ מִדְיָֽן׃ס","ţȧ֣ẖaţ ʼá֔wen ráʼi֖yţiy ʼáholé֣y kẇşá֑̌n yirĕgĕ̇z֕ẇ⁠n yĕriyʻ֖wòţ ʼe֥reẕ midĕyáֽn׃s"],[3,8,"הֲ⁠בִ⁠נְהָרִים֙ חָרָ֣ה יְהוָ֔ה אִ֤ם בַּ⁠נְּהָרִים֙ אַפֶּ֔⁠ךָ אִם־בַּ⁠יָּ֖ם עֶבְרָתֶ֑⁠ךָ כִּ֤י תִרְכַּב֙ עַל־סוּסֶ֔י⁠ךָ מַרְכְּבֹתֶ֖י⁠ךָ יְשׁוּעָֽה׃","hà⁠bi⁠nĕháriym֙ ẖárá֣h yĕhwá֔h ʼi֤m bȧ⁠nĕ̇háriym֙ ʼapė֔⁠ká ʼim-bȧ⁠yá֖̇m ʻebĕráţe֑⁠ká ki֤̇y ţirĕkȧb֙ ʻal-sẇse֔y⁠ká marĕkĕ̇bòţe֖y⁠ká yĕş̌ẇʻáֽh׃"],[3,9,"עֶרְיָ֤ה תֵעוֹר֙ קַשְׁתֶּ֔⁠ךָ שְׁבֻע֥וֹת מַטּ֖וֹת אֹ֣מֶר סֶ֑לָה נְהָר֖וֹת תְּבַקַּע־אָֽרֶץ׃","ʻerĕyá֤h ţéʻwòr֙ qaşĕ̌ţė֔⁠ká şĕ̌buʻ֥wòţ maṫ֖wòţ ʼò֣mer se֑láh nĕhár֖wòţ ţĕ̇baqȧʻ-ʼáֽreẕ׃"],[3,10,"רָא֤וּ⁠ךָ יָחִ֨ילוּ֙ הָרִ֔ים זֶ֥רֶם מַ֖יִם עָבָ֑ר נָתַ֤ן תְּהוֹם֙ קוֹל֔⁠וֹ ר֖וֹם יָדֵ֥י⁠הוּ נָשָֽׂא׃","ráʼ֤ẇ⁠ká yáẖi֨ylẇ֙ hári֔ym ze֥rem ma֖yim ʻábá֑r náţa֤n ţĕ̇hwòm֙ qwòl֔⁠wò r֖wòm yádé֥y⁠hẇ náşáֽ̂ʼ׃"],[3,11,"שֶׁ֥מֶשׁ יָרֵ֖חַ עָ֣מַד זְבֻ֑לָ⁠ה לְ⁠א֤וֹר חִצֶּ֨י⁠ךָ֙ יְהַלֵּ֔כוּ לְ⁠נֹ֖גַהּ בְּרַ֥ק חֲנִיתֶֽ⁠ךָ׃","şě֥meş̌ yáré֖ẖa ʻá֣mad zĕbu֑lá⁠h lĕ⁠ʼ֤wòr ẖiẕė֨y⁠ká֙ yĕhalé̇֔kẇ lĕ⁠nò֖gaḣ bĕ̇ra֥q ẖàniyţeֽ⁠ká׃"],[3,12,"בְּ⁠זַ֖עַם תִּצְעַד־אָ֑רֶץ בְּ⁠אַ֖ף תָּד֥וּשׁ גּוֹיִֽם׃","bĕ̇⁠za֖ʻam ţi̇ẕĕʻad-ʼá֑reẕ bĕ̇⁠ʼa֖p ţá̇d֥ẇş̌ ġwòyiֽm׃"],[3,13,"יָצָ֨אתָ֙ לְ⁠יֵ֣שַׁע עַמֶּ֔⁠ךָ לְ⁠יֵ֖שַׁע אֶת־מְשִׁיחֶ֑⁠ךָ מָחַ֤צְתָּ רֹּאשׁ֙ מִ⁠בֵּ֣ית רָשָׁ֔ע עָר֛וֹת יְס֥וֹד עַד־צַוָּ֖אר סֶֽלָה׃פ","yáẕá֨ʼţá֙ lĕ⁠yé֣şǎʻ ʻamė֔⁠ká lĕ⁠yé֖şǎʻ ʼeţ-mĕşǐyẖe֑⁠ká máẖa֤ẕĕţá̇ rò̇ʼş̌֙ mi⁠bé֣̇yţ ráşá̌֔ʻ ʻár֛wòţ yĕs֥wòd ʻad-ẕawá֖̇ʼr seֽláh׃p"],[3,14,"נָקַ֤בְתָּ בְ⁠מַטָּי⁠ו֙ רֹ֣אשׁ פרז⁠ו יִסְעֲר֖וּ לַ⁠הֲפִיצֵ֑⁠נִי עֲלִ֣יצֻתָ֔⁠ם כְּמוֹ־לֶ⁠אֱכֹ֥ל עָנִ֖י בַּ⁠מִּסְתָּֽר׃","náqa֤bĕţá̇ bĕ⁠matá̇y⁠w֙ rò֣ʼş̌ prz⁠w yisĕʻàr֖ẇ la⁠hàpiyẕé֑⁠niy ʻàli֣yẕuţá֔⁠m kĕ̇mwò-le⁠ʼèkò֥l ʻáni֖y bȧ⁠mi̇sĕţáֽ̇r׃"],[3,15,"דָּרַ֥כְתָּ בַ⁠יָּ֖ם סוּסֶ֑י⁠ךָ חֹ֖מֶר מַ֥יִם רַבִּֽים׃","dá̇ra֥kĕţá̇ ba⁠yá֖̇m sẇse֑y⁠ká ẖò֖mer ma֥yim rabiֽ̇ym׃"],[3,16,"שָׁמַ֣עְתִּי ׀ וַ⁠תִּרְגַּ֣ז בִּטְנִ֗⁠י לְ⁠קוֹל֙ צָלֲל֣וּ שְׂפָתַ֔⁠י יָב֥וֹא רָקָ֛ב בַּ⁠עֲצָמַ֖⁠י וְ⁠תַחְתַּ֣⁠י אֶרְגָּ֑ז אֲשֶׁ֤ר אָנ֨וּחַ֙ לְ⁠י֣וֹם צָרָ֔ה לַ⁠עֲל֖וֹת לְ⁠עַ֥ם יְגוּדֶֽ⁠נּוּ׃","şá̌ma֣ʻĕţi̇y ׀ wa⁠ţi̇rĕgȧ֣z bi̇tĕni֗⁠y lĕ⁠qwòl֙ ẕálàl֣ẇ şĕ̂páţa֔⁠y yáb֥wòʼ ráqá֛b bȧ⁠ʻàẕáma֖⁠y wĕ⁠ţaẖĕţȧ֣⁠y ʼerĕgá֑̇z ʼàşě֤r ʼán֨ẇẖa֙ lĕ⁠y֣wòm ẕárá֔h la⁠ʻàl֖wòţ lĕ⁠ʻa֥m yĕgẇdeֽ⁠ṅẇ׃"],[3,17,"כִּֽי־תְאֵנָ֣ה לֹֽא־תִפְרָ֗ח וְ⁠אֵ֤ין יְבוּל֙ בַּ⁠גְּפָנִ֔ים כִּחֵשׁ֙ מַעֲשֵׂה־זַ֔יִת וּ⁠שְׁדֵמ֖וֹת לֹא־עָ֣שָׂה אֹ֑כֶל גָּזַ֤ר מִ⁠מִּכְלָה֙ צֹ֔אן וְ⁠אֵ֥ין בָּקָ֖ר בָּ⁠רְפָתִֽים׃","kiֽ̇y-ţĕʼéná֣h lòֽʼ-ţipĕrá֗ẖ wĕ⁠ʼé֤yn yĕbẇl֙ bȧ⁠gĕ̇páni֔ym ki̇ẖéş̌֙ maʻàşé̂h-za֔yiţ ẇ⁠şĕ̌dém֖wòţ lòʼ-ʻá֣şá̂h ʼò֑kel gá̇za֤r mi⁠mi̇kĕláh֙ ẕò֔ʼn wĕ⁠ʼé֥yn bá̇qá֖r bá̇⁠rĕpáţiֽym׃"],[3,18,"וַ⁠אֲנִ֖י בַּ⁠יהוָ֣ה אֶעְל֑וֹזָה אָגִ֖ילָה בֵּ⁠אלֹהֵ֥י יִשְׁעִֽ⁠י׃","wa⁠ʼàni֖y bȧ⁠yhwá֣h ʼeʻĕl֑wòzáh ʼági֖yláh bé̇⁠ʼlòhé֥y yişĕ̌ʻiֽ⁠y׃"],[3,19,"יְהוִ֤הּ אֲדֹנָ⁠י֙ חֵילִ֔⁠י וַ⁠יָּ֤שֶׂם רַגְלַ⁠י֙ כָּֽ⁠אַיָּל֔וֹת וְ⁠עַ֥ל בָּמוֹתַ֖⁠י יַדְרִכֵ֑⁠נִי לַ⁠מְנַצֵּ֖חַ בִּ⁠נְגִינוֹתָֽי׃","yĕhwi֤ḣ ʼàdòná⁠y֙ ẖéyli֔⁠y wa⁠yá֤̇şêm ragĕla⁠y֙ káֽ̇⁠ʼayá̇l֔wòţ wĕ⁠ʻa֥l bá̇mwòţa֖⁠y yadĕriké֑⁠niy la⁠mĕnaẕé֖̇ẖa bi̇⁠nĕgiynwòţáֽy׃"]],"fra-lsg1910":[[1,1,"Oracle révélé à Habakuk, le prophète.","Oracle révélé à Habakuk, le prophète."],[1,2,"Jusqu'à quand, ô Éternel?... J'ai crié, Et tu n'écoutes pas! J'ai crié vers toi à la violence, Et tu ne secours pas!","Jusqu'à quand, ô Éternel?... J'ai crié, Et tu n'écoutes pas! J'ai crié vers toi à la violence, Et tu ne secours pas!"],[1,3,"Pourquoi me fais-tu voir l'iniquité, Et contemples-tu l'injustice? Pourquoi l'oppression et la violence sont-elles devant moi? Il y a des querelles, et la discorde s'élève.","Pourquoi me fais-tu voir l'iniquité, Et contemples-tu l'injustice? Pourquoi l'oppression et la violence sont-elles devant moi? Il y a des querelles, et la discorde s'élève."],[1,4,"Aussi la loi n'a point de vie, La justice n'a point de force; Car le méchant triomphe du juste, Et l'on rend des jugements iniques.","Aussi la loi n'a point de vie, La justice n'a point de force; Car le méchant triomphe du juste, Et l'on rend des jugements iniques."],[1,5,"Jetez les yeux parmi les nations, regardez, Et soyez saisis d'étonnement, d'épouvante! Car je vais faire en vos jours une oeuvre, Que vous ne croiriez pas si on la racontait.","Jetez les yeux parmi les nations, regardez, Et soyez saisis d'étonnement, d'épouvante! Car je vais faire en vos jours une oeuvre, Que vous ne croiriez pas si on la racontait."],[1,6,"Voici, je vais susciter les Chaldéens, Peuple furibond et impétueux, Qui traverse de vastes étendues de pays, Pour s'emparer de demeures qui ne sont pas à lui.","Voici, je vais susciter les Chaldéens, Peuple furibond et impétueux, Qui traverse de vastes étendues de pays, Pour s'emparer de demeures qui ne sont pas à lui."],[1,7,"Il est terrible et formidable; De lui seul viennent son droit et sa grandeur.","Il est terrible et formidable; De lui seul viennent son droit et sa grandeur."],[1,8,"Ses chevaux sont plus rapides que les léopards, Plus agiles que les loups du soir, Et ses cavaliers s'avancent avec orgueil; Ses cavaliers arrivent de loin, Ils volent comme l'aigle qui fond sur sa proie.","Ses chevaux sont plus rapides que les léopards, Plus agiles que les loups du soir, Et ses cavaliers s'avancent avec orgueil; Ses cavaliers arrivent de loin, Ils volent comme l'aigle qui fond sur sa proie."],[1,9,"Tout ce peuple vient pour se livrer au pillage; Ses regards avides se portent en avant, Et il assemble des prisonniers comme du sable.","Tout ce peuple vient pour se livrer au pillage; Ses regards avides se portent en avant, Et il assemble des prisonniers comme du sable."],[1,10,"Il se moque des rois, Et les princes font l'objet de ses railleries; Il se rit de toutes les forteresses, Il amoncelle de la terre, et il les prend.","Il se moque des rois, Et les princes font l'objet de ses railleries; Il se rit de toutes les forteresses, Il amoncelle de la terre, et il les prend."],[1,11,"Alors son ardeur redouble, Il poursuit sa marche, et il se rend coupable. Sa force à lui, voilà son dieu!","Alors son ardeur redouble, Il poursuit sa marche, et il se rend coupable. Sa force à lui, voilà son dieu!"],[1,12,"N'es-tu pas de toute éternité, Éternel, mon Dieu, mon Saint? Nous ne mourrons pas! O Éternel, tu as établi ce peuple pour exercer tes jugements; O mon rocher, tu l'as suscité pour infliger tes châtiments.","N'es-tu pas de toute éternité, Éternel, mon Dieu, mon Saint? Nous ne mourrons pas! O Éternel, tu as établi ce peuple pour exercer tes jugements; O mon rocher, tu l'as suscité pour infliger tes châtiments."],[1,13,"Tes yeux sont trop purs pour voir le mal, Et tu ne peux pas regarder l'iniquité. Pourquoi regarderais-tu les perfides, et te tairais-tu, Quand le méchant dévore celui qui est plus juste que lui?","Tes yeux sont trop purs pour voir le mal, Et tu ne peux pas regarder l'iniquité. Pourquoi regarderais-tu les perfides, et te tairais-tu, Quand le méchant dévore celui qui est plus juste que lui?"],[1,14,"Traiterais-tu l'homme comme les poissons de la mer, Comme le reptile qui n'a point de maître?","Traiterais-tu l'homme comme les poissons de la mer, Comme le reptile qui n'a point de maître?"],[1,15,"Il les fait tous monter avec l'hameçon, Il les attire dans son filet, Il les assemble dans ses rets: Aussi est-il dans la joie et dans l'allégresse.","Il les fait tous monter avec l'hameçon, Il les attire dans son filet, Il les assemble dans ses rets: Aussi est-il dans la joie et dans l'allégresse."],[1,16,"C'est pourquoi il sacrifie à son filet, Il offre de l'encens à ses rets; Car par eux sa portion est grasse, Et sa nourriture succulente.","C'est pourquoi il sacrifie à son filet, Il offre de l'encens à ses rets; Car par eux sa portion est grasse, Et sa nourriture succulente."],[1,17,"Videra-t-il pour cela son filet, Et toujours égorgera-t-il sans pitié les nations?","Videra-t-il pour cela son filet, Et toujours égorgera-t-il sans pitié les nations?"],[2,1,"J'étais à mon poste, Et je me tenais sur la tour; Je veillais, pour voir ce que l'Éternel me dirait, Et ce que je répliquerais après ma plainte.","J'étais à mon poste, Et je me tenais sur la tour; Je veillais, pour voir ce que l'Éternel me dirait, Et ce que je répliquerais après ma plainte."],[2,2,"L'Éternel m'adressa la parole, et il dit: Écris la prophétie: Grave-la sur des tables, Afin qu'on la lise couramment.","L'Éternel m'adressa la parole, et il dit: Écris la prophétie: Grave-la sur des tables, Afin qu'on la lise couramment."],[2,3,"Car c'est une prophétie dont le temps est déjà fixé, Elle marche vers son terme, et elle ne mentira pas; Si elle tarde, attends-la, Car elle s'accomplira, elle s'accomplira certainement.","Car c'est une prophétie dont le temps est déjà fixé, Elle marche vers son terme, et elle ne mentira pas; Si elle tarde, attends-la, Car elle s'accomplira, elle s'accomplira certainement."],[2,4,"Voici, son âme s'est enflée, elle n'est pas droite en lui; Mais le juste vivra par sa foi.","Voici, son âme s'est enflée, elle n'est pas droite en lui; Mais le juste vivra par sa foi."],[2,5,"Pareil à celui qui est ivre et arrogant, L'orgueilleux ne demeure pas tranquille; Il élargit sa bouche comme le séjour des morts, Il est insatiable comme la mort; Il attire à lui toutes les nations, Il assemble auprès de lui tous les peuples.","Pareil à celui qui est ivre et arrogant, L'orgueilleux ne demeure pas tranquille; Il élargit sa bouche comme le séjour des morts, Il est insatiable comme la mort; Il attire à lui toutes les nations, Il assemble auprès de lui tous les peuples."],[2,6,"Ne sera-t-il pas pour tous un sujet de sarcasme, De railleries et d'énigmes? On dira: Malheur à celui qui accumule ce qui n'est pas à lui! Jusques à quand?... Malheur à celui qui augmente le fardeau de ses dettes!","Ne sera-t-il pas pour tous un sujet de sarcasme, De railleries et d'énigmes? On dira: Malheur à celui qui accumule ce qui n'est pas à lui! Jusques à quand?... Malheur à celui qui augmente le fardeau de ses dettes!"],[2,7,"Tes créanciers ne se lèveront-ils pas soudain? Tes oppresseurs ne se réveilleront-ils pas? Et tu deviendras leur proie.","Tes créanciers ne se lèveront-ils pas soudain? Tes oppresseurs ne se réveilleront-ils pas? Et tu deviendras leur proie."],[2,8,"Parce que tu as pillé beaucoup de nations, Tout le reste des peuples te pillera; Car tu as répandu le sang des hommes, Tu as commis des violences dans le pays, Contre la ville et tous ses habitants.","Parce que tu as pillé beaucoup de nations, Tout le reste des peuples te pillera; Car tu as répandu le sang des hommes, Tu as commis des violences dans le pays, Contre la ville et tous ses habitants."],[2,9,"Malheur à celui qui amasse pour sa maison des gains iniques, Afin de placer son nid dans un lieu élevé, Pour se garantir de la main du malheur!","Malheur à celui qui amasse pour sa maison des gains iniques, Afin de placer son nid dans un lieu élevé, Pour se garantir de la main du malheur!"],[2,10,"C'est l'opprobre de ta maison que tu as résolu, En détruisant des peuples nombreux, Et c'est contre toi-même que tu as péché.","C'est l'opprobre de ta maison que tu as résolu, En détruisant des peuples nombreux, Et c'est contre toi-même que tu as péché."],[2,11,"Car la pierre crie du milieu de la muraille, Et le bois qui lie la charpente lui répond.","Car la pierre crie du milieu de la muraille, Et le bois qui lie la charpente lui répond."],[2,12,"Malheur à celui qui bâtit une ville avec le sang, Qui fonde une ville avec l'iniquité!","Malheur à celui qui bâtit une ville avec le sang, Qui fonde une ville avec l'iniquité!"],[2,13,"Voici, quand l'Éternel des armées l'a résolu, Les peuples travaillent pour le feu, Les nations se fatiguent en vain.","Voici, quand l'Éternel des armées l'a résolu, Les peuples travaillent pour le feu, Les nations se fatiguent en vain."],[2,14,"Car la terre sera remplie de la connaissance de la gloire de l'Éternel, Comme le fond de la mer par les eaux qui le couvrent.","Car la terre sera remplie de la connaissance de la gloire de l'Éternel, Comme le fond de la mer par les eaux qui le couvrent."],[2,15,"Malheur à celui qui fait boire son prochain, À toi qui verses ton outre et qui l'enivres, Afin de voir sa nudité!","Malheur à celui qui fait boire son prochain, À toi qui verses ton outre et qui l'enivres, Afin de voir sa nudité!"],[2,16,"Tu seras rassasié de honte plus que de gloire; Bois aussi toi-même, et découvre-toi! La coupe de la droite de l'Éternel se tournera vers toi, Et l'ignominie souillera ta gloire.","Tu seras rassasié de honte plus que de gloire; Bois aussi toi-même, et découvre-toi! La coupe de la droite de l'Éternel se tournera vers toi, Et l'ignominie souillera ta gloire."],[2,17,"Car les violences contre le Liban retomberont sur toi, Et les ravages des bêtes t'effraieront, Parce que tu as répandu le sang des hommes, Et commis des violences dans le pays, Contre la ville et tous ses habitants.","Car les violences contre le Liban retomberont sur toi, Et les ravages des bêtes t'effraieront, Parce que tu as répandu le sang des hommes, Et commis des violences dans le pays, Contre la ville et tous ses habitants."],[2,18,"À quoi sert une image taillée, pour qu'un ouvrier la taille? À quoi sert une image en fonte et qui enseigne le mensonge, Pour que l'ouvrier qui l'a faite place en elle sa confiance, Tandis qu'il fabrique des idoles muettes?","À quoi sert une image taillée, pour qu'un ouvrier la taille? À quoi sert une image en fonte et qui enseigne le mensonge, Pour que l'ouvrier qui l'a faite place en elle sa confiance, Tandis qu'il fabrique des idoles muettes?"],[2,19,"Malheur à celui qui dit au bois: Lève-toi! À une pierre muette: Réveille-toi! Donnera-t-elle instruction? Voici, elle est garnie d'or et d'argent, Mais il n'y a point en elle un esprit qui l'anime.","Malheur à celui qui dit au bois: Lève-toi! À une pierre muette: Réveille-toi! Donnera-t-elle instruction? Voici, elle est garnie d'or et d'argent, Mais il n'y a point en elle un esprit qui l'anime."],[2,20,"L'Éternel est dans son saint temple. Que toute la terre fasse silence devant lui!","L'Éternel est dans son saint temple. Que toute la terre fasse silence devant lui!"],[3,1,"Prière d'Habakuk, le prophète. (Sur le mode des complaintes.)","Prière d'Habakuk, le prophète. (Sur le mode des complaintes.)"],[3,2,"Éternel, j'ai entendu ce que tu as annoncé, je suis saisi de crainte. Accomplis ton oeuvre dans le cours des années, ô Éternel! Dans le cours des années manifeste-la! Mais dans ta colère souviens-toi de tes compassions!","Éternel, j'ai entendu ce que tu as annoncé, je suis saisi de crainte. Accomplis ton oeuvre dans le cours des années, ô Éternel! Dans le cours des années manifeste-la! Mais dans ta colère souviens-toi de tes compassions!"],[3,3,"Dieu vient de Théman, Le Saint vient de la montagne de Paran... Pause. Sa majesté couvre les cieux, Et sa gloire remplit la terre.","Dieu vient de Théman, Le Saint vient de la montagne de Paran... Pause. Sa majesté couvre les cieux, Et sa gloire remplit la terre."],[3,4,"C'est comme l'éclat de la lumière; Des rayons partent de sa main; Là réside sa force.","C'est comme l'éclat de la lumière; Des rayons partent de sa main; Là réside sa force."],[3,5,"Devant lui marche la peste, Et la peste est sur ses traces.","Devant lui marche la peste, Et la peste est sur ses traces."],[3,6,"Il s'arrête, et de l'oeil il mesure la terre; Il regarde, et il fait trembler les nations; Les montagnes éternelles se brisent, Les collines antiques s'abaissent; Les sentiers d'autrefois s'ouvrent devant lui.","Il s'arrête, et de l'oeil il mesure la terre; Il regarde, et il fait trembler les nations; Les montagnes éternelles se brisent, Les collines antiques s'abaissent; Les sentiers d'autrefois s'ouvrent devant lui."],[3,7,"Je vois dans la détresse les tentes de l'Éthiopie, Et les tentes du pays de Madian sont dans l'épouvante.","Je vois dans la détresse les tentes de l'Éthiopie, Et les tentes du pays de Madian sont dans l'épouvante."],[3,8,"L'Éternel est-il irrité contre les fleuves? Est-ce contre les fleuves que s'enflamme ta colère, Contre la mer que se répand ta fureur, Pour que tu sois monté sur tes chevaux, Sur ton char de victoire?","L'Éternel est-il irrité contre les fleuves? Est-ce contre les fleuves que s'enflamme ta colère, Contre la mer que se répand ta fureur, Pour que tu sois monté sur tes chevaux, Sur ton char de victoire?"],[3,9,"Ton arc est mis à nu; Les malédictions sont les traits de ta parole... Pause. Tu fends la terre pour donner cours aux fleuves.","Ton arc est mis à nu; Les malédictions sont les traits de ta parole... Pause. Tu fends la terre pour donner cours aux fleuves."],[3,10,"À ton aspect, les montagnes tremblent; Des torrents d'eau se précipitent; L'abîme fait entendre sa voix, Il lève ses mains en haut.","À ton aspect, les montagnes tremblent; Des torrents d'eau se précipitent; L'abîme fait entendre sa voix, Il lève ses mains en haut."],[3,11,"Le soleil et la lune s'arrêtent dans leur demeure, À la lumière de tes flèches qui partent, À la clarté de ta lance qui brille.","Le soleil et la lune s'arrêtent dans leur demeure, À la lumière de tes flèches qui partent, À la clarté de ta lance qui brille."],[3,12,"Tu parcours la terre dans ta fureur, Tu écrases les nations dans ta colère.","Tu parcours la terre dans ta fureur, Tu écrases les nations dans ta colère."],[3,13,"Tu sors pour délivrer ton peuple, Pour délivrer ton oint; Tu brises le faîte de la maison du méchant, Tu la détruis de fond en comble. Pause.","Tu sors pour délivrer ton peuple, Pour délivrer ton oint; Tu brises le faîte de la maison du méchant, Tu la détruis de fond en comble. Pause."],[3,14,"Tu perces de tes traits la tête de ses chefs, Qui se précipitent comme la tempête pour me disperser, Poussant des cris de joie, Comme s'ils dévoraient déjà le malheureux dans leur repaire.","Tu perces de tes traits la tête de ses chefs, Qui se précipitent comme la tempête pour me disperser, Poussant des cris de joie, Comme s'ils dévoraient déjà le malheureux dans leur repaire."],[3,15,"Avec tes chevaux tu foules la mer, La boue des grandes eaux.","Avec tes chevaux tu foules la mer, La boue des grandes eaux."],[3,16,"J'ai entendu... Et mes entrailles sont émues. À cette voix, mes lèvres frémissent, Mes os se consument, Et mes genoux chancellent: En silence je dois attendre le jour de la détresse, Le jour où l'oppresseur marchera contre le peuple.","J'ai entendu... Et mes entrailles sont émues. À cette voix, mes lèvres frémissent, Mes os se consument, Et mes genoux chancellent: En silence je dois attendre le jour de la détresse, Le jour où l'oppresseur marchera contre le peuple."],[3,17,"Car le figuier ne fleurira pas, La vigne ne produira rien, Le fruit de l'olivier manquera, Les champs ne donneront pas de nourriture; Les brebis disparaîtront du pâturage, Et il n'y aura plus de boeufs dans les étables.","Car le figuier ne fleurira pas, La vigne ne produira rien, Le fruit de l'olivier manquera, Les champs ne donneront pas de nourriture; Les brebis disparaîtront du pâturage, Et il n'y aura plus de boeufs dans les étables."],[3,18,"Toutefois, je veux me réjouir en l'Éternel, Je veux me réjouir dans le Dieu de mon salut.","Toutefois, je veux me réjouir en l'Éternel, Je veux me réjouir dans le Dieu de mon salut."],[3,19,"L'Éternel, le Seigneur, est ma force; Il rend mes pieds semblables à ceux des biches, Et il me fait marcher sur mes lieux élevés. Au chef des chantres. Avec instruments à cordes.","L'Éternel, le Seigneur, est ma force; Il rend mes pieds semblables à ceux des biches, Et il me fait marcher sur mes lieux élevés. Au chef des chantres. Avec instruments à cordes."]],"spa-rv1909":[[1,1,"LA cargaquevióHabacucprofeta.","LA cargaquevióHabacucprofeta."],[1,2,"¿Hastacuándo, oh Jehová, clamaré, y nooirás; ydaré vocesá ti á causa de la violencia, y nosalvarás?","¿Hastacuándo, oh Jehová, clamaré, y nooirás; ydaré vocesá ti á causa de la violencia, y nosalvarás?"],[1,3,"¿Por quéme haces veriniquidad, y haces que miremolestia, y sacoy violenciadelantede mí, habiendo además quien levantepleitoy contienda?","¿Por quéme haces veriniquidad, y haces que miremolestia, y sacoy violenciadelantede mí, habiendo además quien levantepleitoy contienda?"],[1,4,"Porlo cualla leyes debilitada, y el juicionosaleverdadero: porcuantoel impíoasedia al justo, poresosaletorcido el juicio.","Porlo cualla leyes debilitada, y el juicionosaleverdadero: porcuantoel impíoasedia al justo, poresosaletorcido el juicio."],[1,5,"Miraden las gentes, y ved, y maravillaospasmosamente; porqueobraserá hecha en vuestros días, que aun cuandose os contare, nola creeréis.","Miraden las gentes, y ved, y maravillaospasmosamente; porqueobraserá hecha en vuestros días, que aun cuandose os contare, nola creeréis."],[1,6,"Porquehe aquí, yo levantolos Caldeos, genteamargay presurosa, que caminapor la anchurade la tierrapara poseerlas habitacionesajenas.","Porquehe aquí, yo levantolos Caldeos, genteamargay presurosa, que caminapor la anchurade la tierrapara poseerlas habitacionesajenas."],[1,7,"Espantosa es y terrible: deellamismasaldrásuderechoy sugrandeza.","Espantosa es y terrible: deellamismasaldrásuderechoy sugrandeza."],[1,8,"Y serán sus caballosmás ligerosque tigres, y más agudosque lobosde tarde; y sus jinetesse multiplicarán: vendránde lejossus caballeros, y volaráncomo águilasque se apresuraná la comida.","Y serán sus caballosmás ligerosque tigres, y más agudosque lobosde tarde; y sus jinetesse multiplicarán: vendránde lejossus caballeros, y volaráncomo águilasque se apresuraná la comida."],[1,9,"Todaella vendráá la presa: delantede sus caras viento solano; y juntarácautivoscomo arena.","Todaella vendráá la presa: delantede sus caras viento solano; y juntarácautivoscomo arena."],[1,10,"Y escarneceráde los reyes, y de los príncipeshará burla: reirásede todafortaleza, y amontonarápolvo, y latomará.","Y escarneceráde los reyes, y de los príncipeshará burla: reirásede todafortaleza, y amontonarápolvo, y latomará."],[1,11,"Luegomudaráespíritu, y pasaráadelante, y ofenderáatribuyendoesta su potenciaá su dios.","Luegomudaráespíritu, y pasaráadelante, y ofenderáatribuyendoesta su potenciaá su dios."],[1,12,"¿Noeres túdesde el principio, oh Jehová, Diosmío, Santomío? Nomoriremos. Oh Jehová, para juiciolo pusiste; y tú, oh Roca, lo fundastepara castigar.","¿Noeres túdesde el principio, oh Jehová, Diosmío, Santomío? Nomoriremos. Oh Jehová, para juiciolo pusiste; y tú, oh Roca, lo fundastepara castigar."],[1,13,"Muy limpioeres de ojospara verel mal, nipuedesverel agravio: ¿por quéveslos menospreciadores, y callascuando destruyeel impíoal más justoqueél,","Muy limpioeres de ojospara verel mal, nipuedesverel agravio: ¿por quéveslos menospreciadores, y callascuando destruyeel impíoal más justoqueél,"],[1,14,"Y hacesque sean los hombrescomo los pecesde la mar, como reptilesque notienen señor?","Y hacesque sean los hombrescomo los pecesde la mar, como reptilesque notienen señor?"],[1,15,"Sacaráá todoscon anzuelo, cogeráloscon su red, y juntarálosen su aljerife: porlo cualse holgaráy hará alegrías.","Sacaráá todoscon anzuelo, cogeráloscon su red, y juntarálosen su aljerife: porlo cualse holgaráy hará alegrías."],[1,16,"Porestohará sacrificiosá su red, y ofrecerá sahumeriosá su aljerife: porquecon ellos engordósu porción, y engrasósu comida.","Porestohará sacrificiosá su red, y ofrecerá sahumeriosá su aljerife: porquecon ellos engordósu porción, y engrasósu comida."],[1,17,"¿Vaciará poresosu red, ó tendrá piedadde matar gentescontinuamente?","¿Vaciará poresosu red, ó tendrá piedadde matar gentescontinuamente?"],[2,1,"SOBREmi guardaestaré, y sobrela fortalezaafirmaréel pie, y atalayarépara verquéhablaráen mí, y quétengo de responderá mi pregunta.","SOBREmi guardaestaré, y sobrela fortalezaafirmaréel pie, y atalayarépara verquéhablaráen mí, y quétengo de responderá mi pregunta."],[2,2,"Y Jehováme respondió, y dijo: Escribela visión, y decláralaentablas, para que corrael que leyereenella.","Y Jehováme respondió, y dijo: Escribela visión, y decláralaentablas, para que corrael que leyereenella."],[2,3,"Aunquela visióntardaráaúnpor tiempo, mas al finhablará, y nomentirá: aunquese tardare, espéralo, que sin dudavendrá; notardará.","Aunquela visióntardaráaúnpor tiempo, mas al finhablará, y nomentirá: aunquese tardare, espéralo, que sin dudavendrá; notardará."],[2,4,"He aquíse enorgulleceaquel cuya almanoes derecha en él: mas el justoen su fevivirá.","He aquíse enorgulleceaquel cuya almanoes derecha en él: mas el justoen su fevivirá."],[2,5,"Y también, por cuanto peca por el vino, esun hombresoberbio, y nopermanecerá: que ensanchócomo el infiernosualma, y es como la muerte, que nose hartará: antes reunióá sítodaslas gentes, y amontonó á sítodoslos pueblos.","Y también, por cuanto peca por el vino, esun hombresoberbio, y nopermanecerá: que ensanchócomo el infiernosualma, y es como la muerte, que nose hartará: antes reunióá sítodaslas gentes, y amontonó á sítodoslos pueblos."],[2,6,"¿Nohan de levantartodosestos sobreél parábola, y sarcasmoscontra él? Y dirán: ¡Aydel que multiplicólo que noera suyo! ¿Y hastacuándohabía de amontonar sobresí espeso lodo?","¿Nohan de levantartodosestos sobreél parábola, y sarcasmoscontra él? Y dirán: ¡Aydel que multiplicólo que noera suyo! ¿Y hastacuándohabía de amontonar sobresí espeso lodo?"],[2,7,"¿Nose levantaránde repentelos que te han de morder, y se despertaránlos que te han de quitar de tu lugar, y serásá ellos por rapiña?","¿Nose levantaránde repentelos que te han de morder, y se despertaránlos que te han de quitar de tu lugar, y serásá ellos por rapiña?"],[2,8,"Porque túhas despojadomuchasgentes, todoslos otrospueblostedespojarán; á causa de las sangreshumanas, y robosde la tierra, de las ciudadesy de todoslos que moraban en ellas.","Porque túhas despojadomuchasgentes, todoslos otrospueblostedespojarán; á causa de las sangreshumanas, y robosde la tierra, de las ciudadesy de todoslos que moraban en ellas."],[2,9,"¡Aydel que codiciamaligna codiciapara su casa, por poneren altosu nido, por escaparsedel poderdel mal!","¡Aydel que codiciamaligna codiciapara su casa, por poneren altosu nido, por escaparsedel poderdel mal!"],[2,10,"Tomaste consejovergonzosopara tu casa, asolastemuchospueblos, y has pecadocontra tu vida.","Tomaste consejovergonzosopara tu casa, asolastemuchospueblos, y has pecadocontra tu vida."],[2,11,"Porquela piedraclamarádesde el muro, y la tabladel enmaderadole responderá.","Porquela piedraclamarádesde el muro, y la tabladel enmaderadole responderá."],[2,12,"¡Aydel que edificala ciudadcon sangres, y del que fundala villacon iniquidad!","¡Aydel que edificala ciudadcon sangres, y del que fundala villacon iniquidad!"],[2,13,"¿Noes esto de Jehováde los ejércitos? Los pueblospues trabajaránpara el fuego, y las gentesse fatigaránen vano.","¿Noes esto de Jehováde los ejércitos? Los pueblospues trabajaránpara el fuego, y las gentesse fatigaránen vano."],[2,14,"Porquela tierraserá llenade conocimientode la gloriade Jehová, como las aguascubrenla mar.","Porquela tierraserá llenade conocimientode la gloriade Jehová, como las aguascubrenla mar."],[2,15,"¡Aydel que da de beberá sus compañeros, que lesacercas tu hiely embriagas, para mirarsus desnudeces!","¡Aydel que da de beberá sus compañeros, que lesacercas tu hiely embriagas, para mirarsus desnudeces!"],[2,16,"Haste llenadode deshonramás que de honra: bebetútambién, y serás descubierto; el cálizde la mano derechade Jehovávolverá sobreti, y vómito de afrentasobretu gloria.","Haste llenadode deshonramás que de honra: bebetútambién, y serás descubierto; el cálizde la mano derechade Jehovávolverá sobreti, y vómito de afrentasobretu gloria."],[2,17,"Porquela rapiñadel Líbanocaerásobre ti, y la destrucciónde las fieraslo quebrantará; á causa de las sangreshumanas, y del robode la tierra, de las ciudades, y de todoslos que en ellas moraban.","Porquela rapiñadel Líbanocaerásobre ti, y la destrucciónde las fieraslo quebrantará; á causa de las sangreshumanas, y del robode la tierra, de las ciudades, y de todoslos que en ellas moraban."],[2,18,"¿De quésirvela esculturaqueesculpióel quela hizo? ¿la estatuade fundición, queenseñamentira, para quehaciendoimágenesmudasconfíeel hacedoren su obra?","¿De quésirvela esculturaqueesculpióel quela hizo? ¿la estatuade fundición, queenseñamentira, para quehaciendoimágenesmudasconfíeel hacedoren su obra?"],[2,19,"¡Aydel que diceal palo: Despiértate; y á la piedramuda: Levántate! ¿Podrá élenseñar? He aquíélestá cubiertode oroy plata, y nohay dentrode élespíritu.","¡Aydel que diceal palo: Despiértate; y á la piedramuda: Levántate! ¿Podrá élenseñar? He aquíélestá cubiertode oroy plata, y nohay dentrode élespíritu."],[2,20,"Mas Jehováestáen su santotemplo: calle delantede él todala tierra.","Mas Jehováestáen su santotemplo: calle delantede él todala tierra."],[3,1,"ORACIÓNde Habacucprofeta, sobreSigionoth.","ORACIÓNde Habacucprofeta, sobreSigionoth."],[3,2,"Oh Jehová, oídohe tu palabra, y temí: oh Jehová, avivatu obraen mediode los tiempos, en mediode los tiemposhazla conocer; en la iraacuérdatede la misericordia.","Oh Jehová, oídohe tu palabra, y temí: oh Jehová, avivatu obraen mediode los tiempos, en mediode los tiemposhazla conocer; en la iraacuérdatede la misericordia."],[3,3,"Diosvendráde Temán, y el Santodel montede Parán. (Selah.) Su gloriacubriólos cielos, y la tierrase llenóde su alabanza.","Diosvendráde Temán, y el Santodel montede Parán. (Selah.) Su gloriacubriólos cielos, y la tierrase llenóde su alabanza."],[3,4,"Y el resplandorfué como la luz; rayosbrillantes salíande su mano; y allíestaba escondida su fortaleza.","Y el resplandorfué como la luz; rayosbrillantes salíande su mano; y allíestaba escondida su fortaleza."],[3,5,"Delantede su rostroibamortandad, y á sus piessalíancarbones encendidos.","Delantede su rostroibamortandad, y á sus piessalíancarbones encendidos."],[3,6,"Paróse, y midióla tierra: miró, é hizo temblarlas gentes; y los montesantiguosfueron desmenuzados, los colladosantiguosse humillaroná él. Sus caminosson eternos.","Paróse, y midióla tierra: miró, é hizo temblarlas gentes; y los montesantiguosfueron desmenuzados, los colladosantiguosse humillaroná él. Sus caminosson eternos."],[3,7,"He vistolas tiendasde Cushánenaflicción; las tiendasde la tierrade Madiántemblaron.","He vistolas tiendasde Cushánenaflicción; las tiendasde la tierrade Madiántemblaron."],[3,8,"¿AiróseJehovácontra los ríos? ¿contra los ríosfué tu enojo? ¿tu iracontra la mar, cuandosubistesobretus caballos, y sobre tus carrosde salud?","¿AiróseJehovácontra los ríos? ¿contra los ríosfué tu enojo? ¿tu iracontra la mar, cuandosubistesobretus caballos, y sobre tus carrosde salud?"],[3,9,"Descubrióseenteramentetu arco, los juramentosá las tribus, palabrasegura. (Selah.) Hendistela tierracon ríos.","Descubrióseenteramentetu arco, los juramentosá las tribus, palabrasegura. (Selah.) Hendistela tierracon ríos."],[3,10,"Viéronte, y tuvieron temorlos montes: pasóla inundaciónde las aguas: el abismodiósu voz, la honduraalzósus manos.","Viéronte, y tuvieron temorlos montes: pasóla inundaciónde las aguas: el abismodiósu voz, la honduraalzósus manos."],[3,11,"El soly la lunase pararonen su estancia: á la luzde tus saetasanduvieron, y al resplandorde tu fulgentelanza.","El soly la lunase pararonen su estancia: á la luzde tus saetasanduvieron, y al resplandorde tu fulgentelanza."],[3,12,"Con irahollastela tierra, con furortrillaste las gentes.","Con irahollastela tierra, con furortrillaste las gentes."],[3,13,"Salistepara salvar tu pueblo, para salvarcon tu ungido. Traspasastela cabezade la casadel impío, desnudandoel cimientohastael cuello. (Selah.)","Salistepara salvar tu pueblo, para salvarcon tu ungido. Traspasastela cabezade la casadel impío, desnudandoel cimientohastael cuello. (Selah.)"],[3,14,"Horadastecon sus báculoslas cabezasde sus villas, que como tempestadacometieron para derramarme: su orgulloera comopara devoraral pobreencubiertamente.","Horadastecon sus báculoslas cabezasde sus villas, que como tempestadacometieron para derramarme: su orgulloera comopara devoraral pobreencubiertamente."],[3,15,"Hiciste camino en la mará tus caballos, por montón de grandesaguas.","Hiciste camino en la mará tus caballos, por montón de grandesaguas."],[3,16,"Oí, y temblómi vientre; á la vozse batieron mis labios; pudriciónse entróen mis huesos, y en mi asientome estremecí; si bienestaré quietoen el díade la angustia, cuando subaal puebloel que lo invadirácon sus tropas.","Oí, y temblómi vientre; á la vozse batieron mis labios; pudriciónse entróen mis huesos, y en mi asientome estremecí; si bienestaré quietoen el díade la angustia, cuando subaal puebloel que lo invadirácon sus tropas."],[3,17,"Aunquela higueranoflorecerá, nien las videshabrá frutos; mentirála obrade la oliva, y los labradosnodarán mantenimiento, ylas ovejasserán quitadasde la majada, y nohabrá vacasen los corrales;","Aunquela higueranoflorecerá, nien las videshabrá frutos; mentirála obrade la oliva, y los labradosnodarán mantenimiento, ylas ovejasserán quitadasde la majada, y nohabrá vacasen los corrales;"],[3,18,"Con todo, yome alegraréen Jehová, y me gozaréen el Diosde misalud.","Con todo, yome alegraréen Jehová, y me gozaréen el Diosde misalud."],[3,19,"Jehováel Señores mi fortaleza, el cual pondrá mis piescomo de ciervas, y me hará andarsobre mis alturas. Al jefe de los cantoressobre mis instrumentosde cuerdas.","Jehováel Señores mi fortaleza, el cual pondrá mis piescomo de ciervas, y me hará andarsobre mis alturas. Al jefe de los cantoressobre mis instrumentosde cuerdas."]],"rus-synodal":[[1,1,"Пророческое видение, которое видел пророк Аввакум.","Proročeskoe videnie, kotoroe videl prorok Avvakum."],[1,2,"Доколе, Господи, я буду взывать, и Ты не слышишь, буду вопиять к Тебе о насилии, и Ты не спасаешь?","Dokole, Gospodi, â budu vzyvatʹ, i Ty ne slyšišʹ, budu vopiâtʹ k Tebe o nasilii, i Ty ne spasaešʹ?"],[1,3,"Для чего даешь мне видеть злодейство и смотреть на бедствия? Грабительство и насилие предо мною, и восстает вражда, и поднимается раздор.","Dlâ čego daešʹ mne videtʹ zlodejstvo i smotretʹ na bedstviâ? Grabitelʹstvo i nasilie predo mnoû, i vosstaet vražda, i podnimaetsâ razdor."],[1,4,"От этого закон потерял силу, и суда правильного нет: так как нечестивый одолевает праведного, то и суд происходит превратный.","Ot étogo zakon poterâl silu, i suda pravilʹnogo net: tak kak nečestivyj odolevaet pravednogo, to i sud proishodit prevratnyj."],[1,5,"Посмотрите между народами и внимательно вглядитесь, и вы сильно изумитесь; ибо Я сделаю во дни ваши такое дело, которому вы не поверили бы, если бы вам рассказывали.","Posmotrite meždu narodami i vnimatelʹno vglâditesʹ, i vy silʹno izumitesʹ; ibo Â sdelaû vo dni vaši takoe delo, kotoromu vy ne poverili by, esli by vam rasskazyvali."],[1,6,"Ибо вот, Я подниму Халдеев, народ жестокий и необузданный, который ходит по широтам земли, чтобы завладеть не принадлежащими ему селениями.","Ibo vot, Â podnimu Haldeev, narod žestokij i neobuzdannyj, kotoryj hodit po širotam zemli, čtoby zavladetʹ ne prinadležaŝimi emu seleniâmi."],[1,7,"Страшен и грозен он; от него самого происходит суд его и власть его.","Strašen i grozen on; ot nego samogo proishodit sud ego i vlastʹ ego."],[1,8,"Быстрее барсов кони его и прытче вечерних волков; скачет в разные стороны конница его; издалека приходят всадники его, прилетают, как орел, бросающийся на добычу.","Bystree barsov koni ego i prytče večernih volkov; skačet v raznye storony konnica ego; izdaleka prihodât vsadniki ego, priletaût, kak orel, brosaûŝijsâ na dobyču."],[1,9,"Весь он идет для грабежа; устремив лицо свое вперед, он забирает пленников, как песок.","Vesʹ on idet dlâ grabeža; ustremiv lico svoe vpered, on zabiraet plennikov, kak pesok."],[1,10,"И над царями он издевается, и князья служат ему посмешищем; над всякою крепостью он смеется: насыплет осадный вал и берет ее.","I nad carâmi on izdevaetsâ, i knâzʹâ služat emu posmešiŝem; nad vsâkoû krepostʹû on smeetsâ: nasyplet osadnyj val i beret ee."],[1,11,"Тогда надмевается дух его, и он ходит и буйствует; сила его – бог его.","Togda nadmevaetsâ duh ego, i on hodit i bujstvuet; sila ego – bog ego."],[1,12,"Но не Ты ли издревле Господь Бог мой, Святой мой? мы не умрем! Ты, Господи, только для суда попустил его. Скала моя! для наказания Ты назначил его.","No ne Ty li izdrevle Gospodʹ Bog moj, Svâtoj moj? my ne umrem! Ty, Gospodi, tolʹko dlâ suda popustil ego. Skala moâ! dlâ nakazaniâ Ty naznačil ego."],[1,13,"Чистым очам Твоим несвойственно глядеть на злодеяния, и смотреть на притеснение Ты не можешь; для чего же Ты смотришь на злодеев и безмолвствуешь, когда нечестивец поглощает того, кто праведнее его,","Čistym očam Tvoim nesvojstvenno glâdetʹ na zlodeâniâ, i smotretʹ na pritesnenie Ty ne možešʹ; dlâ čego že Ty smotrišʹ na zlodeev i bezmolvstvuešʹ, kogda nečestivec pogloŝaet togo, kto pravednee ego,"],[1,14,"и оставляешь людей как рыбу в море, как пресмыкающихся, у которых нет властителя?","i ostavlâešʹ lûdej kak rybu v more, kak presmykaûŝihsâ, u kotoryh net vlastitelâ?"],[1,15,"Всех их таскает удою, захватывает в сеть свою и забирает их в неводы свои, и оттого радуется и торжествует.","Vseh ih taskaet udoû, zahvatyvaet v setʹ svoû i zabiraet ih v nevody svoi, i ottogo raduetsâ i toržestvuet."],[1,16,"За то приносит жертвы сети своей и кадит неводу своему, потому что от них тучна часть его и роскошна пища его.","Za to prinosit žertvy seti svoej i kadit nevodu svoemu, potomu čto ot nih tučna častʹ ego i roskošna piŝa ego."],[1,17,"Неужели для этого он должен опорожнять свою сеть и непрестанно избивать народы без пощады?","Neuželi dlâ étogo on dolžen oporožnâtʹ svoû setʹ i neprestanno izbivatʹ narody bez poŝady?"],[2,1,"На стражу мою стал я и, стоя на башне, наблюдал, чтобы узнать, что скажет Он во мне и что мне отвечать по жалобе моей?","Na stražu moû stal â i, stoâ na bašne, nablûdal, čtoby uznatʹ, čto skažet On vo mne i čto mne otvečatʹ po žalobe moej?"],[2,2,"И отвечал мне Господь и сказал: запиши видение и начертай ясно на скрижалях, чтобы читающий легко мог прочитать,","I otvečal mne Gospodʹ i skazal: zapiši videnie i načertaj âsno na skrižalâh, čtoby čitaûŝij legko mog pročitatʹ,"],[2,3,"ибо видение относится еще к определенному времени и говорит о конце и не обманет; и хотя бы и замедлило, жди его, ибо непременно сбудется, не отменится.","ibo videnie otnositsâ eŝe k opredelennomu vremeni i govorit o konce i ne obmanet; i hotâ by i zamedlilo, ždi ego, ibo nepremenno sbudetsâ, ne otmenitsâ."],[2,4,"Вот, душа надменная не успокоится, а праведный своею верою жив будет.","Vot, duša nadmennaâ ne uspokoitsâ, a pravednyj svoeû veroû živ budet."],[2,5,"Надменный человек, как бродящее вино, не успокаивается, так что расширяет душу свою, как ад, и как смерть он ненасытен, и собирает к себе все народы, и захватывает себе все племена.","Nadmennyj čelovek, kak brodâŝee vino, ne uspokaivaetsâ, tak čto rasširâet dušu svoû, kak ad, i kak smertʹ on nenasyten, i sobiraet k sebe vse narody, i zahvatyvaet sebe vse plemena."],[2,6,"Но не все ли они будут произносить о нем притчу и насмешливую песнь: «горе тому, кто без меры обогащает себя не своим, – надолго ли? – и обременяет себя залогами!»","No ne vse li oni budut proiznositʹ o nem pritču i nasmešlivuû pesnʹ: «gore tomu, kto bez mery obogaŝaet sebâ ne svoim, – nadolgo li? – i obremenâet sebâ zalogami!»"],[2,7,"Не восстанут ли внезапно те, которые будут терзать тебя, и не поднимутся ли против тебя грабители, и ты достанешься им на расхищение?","Ne vosstanut li vnezapno te, kotorye budut terzatʹ tebâ, i ne podnimutsâ li protiv tebâ grabiteli, i ty dostanešʹsâ im na rashiŝenie?"],[2,8,"Так как ты ограбил многие народы, то и тебя ограбят все остальные народы за пролитие крови человеческой, за разорение страны, города и всех живущих в нем.","Tak kak ty ograbil mnogie narody, to i tebâ ograbât vse ostalʹnye narody za prolitie krovi čelovečeskoj, za razorenie strany, goroda i vseh živuŝih v nem."],[2,9,"Горе тому, кто жаждет неправедных приобретений для дома своего, чтобы устроить гнездо свое на высоте и тем обезопасить себя от руки несчастья!","Gore tomu, kto žaždet nepravednyh priobretenij dlâ doma svoego, čtoby ustroitʹ gnezdo svoe na vysote i tem obezopasitʹ sebâ ot ruki nesčastʹâ!"],[2,10,"Бесславие измыслил ты для твоего дома, истребляя многие народы, и согрешил против души твоей.","Besslavie izmyslil ty dlâ tvoego doma, istreblââ mnogie narody, i sogrešil protiv duši tvoej."],[2,11,"Камни из стен возопиют, и перекладины из дерева будут отвечать им:","Kamni iz sten vozopiût, i perekladiny iz dereva budut otvečatʹ im:"],[2,12,"«Горе строящему город на крови и созидающему крепости неправдою!»","«Gore stroâŝemu gorod na krovi i sozidaûŝemu kreposti nepravdoû!»"],[2,13,"Вот, не от Господа ли Саваофа это, что народы трудятся для огня и племена мучат себя напрасно?","Vot, ne ot Gospoda li Savaofa éto, čto narody trudâtsâ dlâ ognâ i plemena mučat sebâ naprasno?"],[2,14,"Ибо земля наполнится познанием славы Господа, как воды наполняют море.","Ibo zemlâ napolnitsâ poznaniem slavy Gospoda, kak vody napolnâût more."],[2,15,"Горе тебе, который подаешь ближнему твоему питье с примесью злобы твоей и делаешь его пьяным, чтобы видеть срамоту его!","Gore tebe, kotoryj podaešʹ bližnemu tvoemu pitʹe s primesʹû zloby tvoej i delaešʹ ego pʹânym, čtoby videtʹ sramotu ego!"],[2,16,"Ты пресытился стыдом вместо славы; пей же и ты и показывай срамоту, – обратится и к тебе чаша десницы Господней и посрамление на славу твою.","Ty presytilsâ stydom vmesto slavy; pej že i ty i pokazyvaj sramotu, – obratitsâ i k tebe čaša desnicy Gospodnej i posramlenie na slavu tvoû."],[2,17,"Ибо злодейство твое на Ливане обрушится на тебя за истребление устрашенных животных, за пролитие крови человеческой, за опустошение страны, города и всех живущих в нем.","Ibo zlodejstvo tvoe na Livane obrušitsâ na tebâ za istreblenie ustrašennyh životnyh, za prolitie krovi čelovečeskoj, za opustošenie strany, goroda i vseh živuŝih v nem."],[2,18,"Что за польза от истукана, сделанного художником, этого литого лжеучителя, хотя ваятель, делая немые кумиры, полагается на свое произведение?","Čto za polʹza ot istukana, sdelannogo hudožnikom, étogo litogo lžeučitelâ, hotâ vaâtelʹ, delaâ nemye kumiry, polagaetsâ na svoe proizvedenie?"],[2,19,"Горе тому, кто говорит дереву: «встань!» и бессловесному камню: «пробудись!» Научит ли он чему-нибудь? Вот, он обложен золотом и серебром, но дыхания в нем нет.","Gore tomu, kto govorit derevu: «vstanʹ!» i besslovesnomu kamnû: «probudisʹ!» Naučit li on čemu-nibudʹ? Vot, on obložen zolotom i serebrom, no dyhaniâ v nem net."],[2,20,"А Господь – во святом храме Своем: да молчит вся земля пред лицом Его!","A Gospodʹ – vo svâtom hrame Svoem: da molčit vsâ zemlâ pred licom Ego!"],[3,1,"Молитва Аввакума пророка, для пения.","Molitva Avvakuma proroka, dlâ peniâ."],[3,2,"Господи! услышал я слух Твой и убоялся. Господи! соверши дело Твое среди лет, среди лет яви его; во гневе вспомни о милости.","Gospodi! uslyšal â sluh Tvoj i uboâlsâ. Gospodi! soverši delo Tvoe sredi let, sredi let âvi ego; vo gneve vspomni o milosti."],[3,3,"Бог от Фемана грядет и Святой – от горы Фаран. Покрыло небеса величие Его, и славою Его наполнилась земля.","Bog ot Femana grâdet i Svâtoj – ot gory Faran. Pokrylo nebesa veličie Ego, i slavoû Ego napolnilasʹ zemlâ."],[3,4,"Блеск ее – как солнечный свет; от руки Его лучи, и здесь тайник Его силы!","Blesk ee – kak solnečnyj svet; ot ruki Ego luči, i zdesʹ tajnik Ego sily!"],[3,5,"Пред лицом Его идет язва, а по стопам Его – жгучий ветер.","Pred licom Ego idet âzva, a po stopam Ego – žgučij veter."],[3,6,"Он стал и поколебал землю; воззрел и в трепет привел народы; вековые горы распались, первобытные холмы опали; пути Его вечные.","On stal i pokolebal zemlû; vozzrel i v trepet privel narody; vekovye gory raspalisʹ, pervobytnye holmy opali; puti Ego večnye."],[3,7,"Грустными видел я шатры Ефиопские; сотряслись палатки земли Мадиамской.","Grustnymi videl â šatry Efiopskie; sotrâslisʹ palatki zemli Madiamskoj."],[3,8,"Разве на реки воспылал, Господи, гнев Твой? разве на реки – негодование Твое, или на море – ярость Твоя, что Ты восшел на коней Твоих, на колесницы Твои спасительные?","Razve na reki vospylal, Gospodi, gnev Tvoj? razve na reki – negodovanie Tvoe, ili na more – ârostʹ Tvoâ, čto Ty vosšel na konej Tvoih, na kolesnicy Tvoi spasitelʹnye?"],[3,9,"Ты обнажил лук Твой по клятвенному обетованию, данному коленам. Ты потоками рассек землю.","Ty obnažil luk Tvoj po klâtvennomu obetovaniû, dannomu kolenam. Ty potokami rassek zemlû."],[3,10,"Увидев Тебя, вострепетали горы, ринулись воды; бездна дала голос свой, высоко подняла руки свои;","Uvidev Tebâ, vostrepetali gory, rinulisʹ vody; bezdna dala golos svoj, vysoko podnâla ruki svoi;"],[3,11,"солнце и луна остановились на месте своем пред светом летающих стрел Твоих, пред сиянием сверкающих копьев Твоих.","solnce i luna ostanovilisʹ na meste svoem pred svetom letaûŝih strel Tvoih, pred siâniem sverkaûŝih kopʹev Tvoih."],[3,12,"Во гневе шествуешь Ты по земле и в негодовании попираешь народы.","Vo gneve šestvuešʹ Ty po zemle i v negodovanii popiraešʹ narody."],[3,13,"Ты выступаешь для спасения народа Твоего, для спасения помазанного Твоего. Ты сокрушаешь главу нечестивого дома, обнажая его от основания до верха.","Ty vystupaešʹ dlâ spaseniâ naroda Tvoego, dlâ spaseniâ pomazannogo Tvoego. Ty sokrušaešʹ glavu nečestivogo doma, obnažaâ ego ot osnovaniâ do verha."],[3,14,"Ты пронзаешь копьями его главу вождей его, когда они, как вихрь, ринулись разбить меня, в радости, как бы думая поглотить бедного скрытно.","Ty pronzaešʹ kopʹâmi ego glavu voždej ego, kogda oni, kak vihrʹ, rinulisʹ razbitʹ menâ, v radosti, kak by dumaâ poglotitʹ bednogo skrytno."],[3,15,"Ты с конями Твоими проложил путь по морю, через пучину великих вод.","Ty s konâmi Tvoimi proložil putʹ po morû, čerez pučinu velikih vod."],[3,16,"Я услышал, и вострепетала внутренность моя; при вести о сем задрожали губы мои, боль проникла в кости мои, и колеблется место подо мною; а я должен быть спокоен в день бедствия, когда придет на народ мой грабитель его.","Â uslyšal, i vostrepetala vnutrennostʹ moâ; pri vesti o sem zadrožali guby moi, bolʹ pronikla v kosti moi, i kolebletsâ mesto podo mnoû; a â dolžen bytʹ spokoen v denʹ bedstviâ, kogda pridet na narod moj grabitelʹ ego."],[3,17,"Хотя бы не расцвела смоковница и не было плода на виноградных лозах, и маслина изменила, и нива не дала пищи, хотя бы не стало овец в загоне и рогатого скота в стойлах, –","Hotâ by ne rascvela smokovnica i ne bylo ploda na vinogradnyh lozah, i maslina izmenila, i niva ne dala piŝi, hotâ by ne stalo ovec v zagone i rogatogo skota v stojlah, –"],[3,18,"но и тогда я буду радоваться о Господе и веселиться о Боге спасения моего.","no i togda â budu radovatʹsâ o Gospode i veselitʹsâ o Boge spaseniâ moego."],[3,19,"Господь Бог – сила моя: Он сделает ноги мои как у оленя и на высоты мои возведет меня! [Начальнику хора.]","Gospodʹ Bog – sila moâ: On sdelaet nogi moi kak u olenâ i na vysoty moi vozvedet menâ! [Načalʹniku hora.]"]],"cmn-cuv-hant":[[1,1,"先知 哈巴谷所得的默示。","xiān zhī hā bā gǔ suǒ dé de mò shì."],[1,2,"他說：耶和華啊！我呼求你， 你不應允，要到幾時呢？ 我因強暴哀求你，你還不拯救。","tā shuō： yé hé huá a！ wǒ hū qiú nǐ， nǐ bù yīng yǔn， yào dào jǐ shí ne？ wǒ yīn qiáng bào āi qiú nǐ， nǐ hái bù zhěng jiù."],[1,3,"你為何使我看見罪孽？ 你為何看着奸惡 而不理呢？ 毀滅和強暴在我面前， 又起了爭端和相鬥的事。","nǐ wèi hé shǐ wǒ kàn jiàn zuì niè？ nǐ wèi hé kàn zhe jiān è ér bù lǐ ne？ huǐ miè hé qiáng bào zài wǒ miàn qián， yòu qǐ le zhēng duān hé xiāng dòu de shì."],[1,4,"因此律法放鬆， 公理也不顯明； 惡人圍困義人， 所以公理顯然顛倒。","yīn cǐ lǜ fǎ fàng sōng， gōng lǐ yě bù xiǎn míng； è rén wéi kùn yì rén， suǒ yǐ gōng lǐ xiǎn rán diān dào."],[1,5,"耶和華說：你們要向列國中觀看， 大大驚奇； 因為在你們的時候，我行一件事， 雖有人告訴你們，你們總是不信。","yé hé huá shuō： nǐ men yào xiàng liè guó zhōng guān kàn， dà dà jīng qí； yīn wèi zài nǐ men de shí hòu， wǒ xíng yī jiàn shì， suī yǒu rén gào sù nǐ men， nǐ men zǒng shì bù xìn."],[1,6,"我必興起 迦勒底人， 就是那殘忍暴躁之民，通行遍地， 佔據那不屬自己的住處。","wǒ bì xìng qǐ jiā lēi dǐ rén， jiù shì nà cán rěn bào zào zhī mín， tōng xíng biàn de， zhàn jù nà bù shǔ zì jǐ de zhù chù."],[1,7,"他威武可畏， 判斷和勢力都任意發出。","tā wēi wǔ kě wèi， pàn duàn hé shì lì dōu rèn yì fā chū."],[1,8,"他的馬比豹更快， 比晚上的豺狼更猛。 馬兵踴躍爭先， 都從遠方而來； 他們飛跑如鷹抓食，","tā de mǎ bǐ bào gèng kuài， bǐ wǎn shàng de chái láng gèng měng. mǎ bīng yǒng yuè zhēng xiān， dōu cóng yuǎn fāng ér lái； tā men fēi pǎo rú yīng zhuā shí，"],[1,9,"都為行強暴而來， 定住臉面向前， 將擄掠的人聚集，多如塵沙。","dōu wèi xíng qiáng bào ér lái， dìng zhù liǎn miàn xiàng qián， jiāng lǔ lüè de rén jù jí， duō rú chén shā."],[1,10,"他們譏誚君王，笑話首領， 嗤笑一切保障，築壘攻取。","tā men jī qiào jūn wáng， xiào huà shǒu lǐng， chī xiào yī qiè bǎo zhàng， zhú lěi gōng qǔ."],[1,11,"他以自己的勢力為神， 像風猛然掃過，顯為有罪。","tā yǐ zì jǐ de shì lì wèi shén， xiàng fēng měng rán sǎo guò， xiǎn wèi yǒu zuì."],[1,12,"耶和華－我的神，我的聖者啊， 你不是從亙古而有嗎？ 我們必不致死。 耶和華啊，你派定他為要刑罰人； 磐石啊，你設立他為要懲治人。","yé hé huá－wǒ de shén， wǒ de shèng zhě a， nǐ bù shì cóng gèn gǔ ér yǒu ma？ wǒ men bì bù zhì sǐ. yé hé huá a， nǐ pài dìng tā wèi yào xíng fá rén； pán shí a， nǐ shè lì tā wèi yào chéng zhì rén."],[1,13,"你眼目清潔， 不看邪僻，不看奸惡； 行詭詐的，你為何看着不理呢？ 惡人吞滅比自己公義的， 你為何靜默不語呢？","nǐ yǎn mù qīng jié， bù kàn xié pì， bù kàn jiān è； xíng guǐ zhà de， nǐ wèi hé kàn zhe bù lǐ ne？ è rén tūn miè bǐ zì jǐ gōng yì de， nǐ wèi hé jìng mò bù yǔ ne？"],[1,14,"你為何使人如海中的魚， 又如沒有管轄的爬物呢？","nǐ wèi hé shǐ rén rú hǎi zhōng de yú， yòu rú méi yǒu guǎn xiá de pá wù ne？"],[1,15,"他用鉤鉤住，用網捕獲， 用拉網聚集他們； 因此，他歡喜快樂，","tā yòng gōu gōu zhù， yòng wǎng bǔ huò， yòng lā wǎng jù jí tā men； yīn cǐ， tā huān xǐ kuài lè，"],[1,16,"就向網獻祭，向網燒香， 因他由此得肥美的分和富裕的食物。","jiù xiàng wǎng xiàn jì， xiàng wǎng shāo xiāng， yīn tā yóu cǐ dé féi měi de fēn hé fù yù de shí wù."],[1,17,"他豈可屢次倒空網羅， 將列國的人時常殺戮，毫不顧惜呢？","tā qǐ kě lǚ cì dào kōng wǎng luó， jiāng liè guó de rén shí cháng shā lù， háo bù gù xī ne？"],[2,1,"我要站在守望所， 立在望樓上觀看， 看耶和華對我說甚麼話， 我可用甚麼話向他訴冤。","wǒ yào zhàn zài shǒu wàng suǒ， lì zài wàng lóu shàng guān kàn， kàn yé hé huá duì wǒ shuō shèn me huà， wǒ kě yòng shèn me huà xiàng tā sù yuān."],[2,2,"他對我說：將這默示明明地寫在版上， 使讀的人容易讀。","tā duì wǒ shuō： jiāng zhè mò shì míng míng de xiě zài bǎn shàng， shǐ dú de rén róng yì dú."],[2,3,"因為這默示有一定的日期， 快要應驗，並不虛謊。 雖然遲延，還要等候； 因為必然臨到，不再遲延。","yīn wèi zhè mò shì yǒu yī dìng de rì qī， kuài yào yīng yàn， bìng bù xū huǎng. suī rán chí yán， hái yào děng hòu； yīn wèi bì rán lín dào， bù zài chí yán."],[2,4,"迦勒底人自高自大，心不正直； 惟義人因信得生。","jiā lēi dǐ rén zì gāo zì dà， xīn bù zhèng zhí； wéi yì rén yīn xìn dé shēng."],[2,5,"迦勒底人因酒詭詐，狂傲， 不住在家中， 擴充心欲，好像陰間。 他如死不能知足， 聚集萬國，堆積萬民都歸自己。","jiā lēi dǐ rén yīn jiǔ guǐ zhà， kuáng ào， bù zhù zài jiā zhōng， kuò chōng xīn yù， hǎo xiàng yīn jiān. tā rú sǐ bù néng zhī zú， jù jí wàn guó， duī jī wàn mín dōu guī zì jǐ."],[2,6,"這些國的民豈不都要提起詩歌並俗語譏刺他說： 禍哉！ 迦勒底人，你增添不屬自己的財物， 多多取人的當頭，要到幾時為止呢？","zhè xiē guó de mín qǐ bù dōu yào tí qǐ shī gē bìng sú yǔ jī cì tā shuō： huò zāi！ jiā lēi dǐ rén， nǐ zēng tiān bù shǔ zì jǐ de cái wù， duō duō qǔ rén de dāng tóu， yào dào jǐ shí wèi zhǐ ne？"],[2,7,"咬傷你的豈不忽然起來， 擾害你的豈不興起， 你就作他們的擄物嗎？","yǎo shāng nǐ de qǐ bù hū rán qǐ lái， rǎo hài nǐ de qǐ bù xìng qǐ， nǐ jiù zuò tā men de lǔ wù ma？"],[2,8,"因你搶奪許多的國，殺人流血， 向國內的城並城中一切居民施行強暴， 所以各國剩下的民都必搶奪你。","yīn nǐ qiǎng duó xǔ duō de guó， shā rén liú xuè， xiàng guó nèi de chéng bìng chéng zhōng yī qiè jū mín shī xíng qiáng bào， suǒ yǐ gè guó shèng xià de mín dōu bì qiǎng duó nǐ."],[2,9,"為本家積蓄不義之財、 在高處搭窩、指望免災的有禍了！","wèi běn jiā jī xù bù yì zhī cái, zài gāo chù dā wō, zhǐ wàng miǎn zāi de yǒu huò le！"],[2,10,"你圖謀剪除多國的民，犯了罪， 使你的家蒙羞，自害己命。","nǐ tú móu jiǎn chú duō guó de mín， fàn le zuì， shǐ nǐ de jiā méng xiū， zì hài jǐ mìng."],[2,11,"牆裏的石頭必呼叫； 房內的棟樑必應聲。","qiáng lǐ de shí tóu bì hū jiào； fáng nèi de dòng liáng bì yīng shēng."],[2,12,"以人血建城、 以罪孽立邑的有禍了！","yǐ rén xuè jiàn chéng, yǐ zuì niè lì yì de yǒu huò le！"],[2,13,"眾民所勞碌得來的被火焚燒， 列國由勞乏而得的歸於虛空， 不都是出於萬軍之耶和華嗎？","zhòng mín suǒ láo lù dé lái de bèi huǒ fén shāo， liè guó yóu láo fá ér dé de guī yú xū kōng， bù dōu shì chū yú wàn jūn zhī yé hé huá ma？"],[2,14,"認識耶和華榮耀的知識要充滿遍地， 好像水充滿洋海一般。","rèn shí yé hé huá róng yào de zhī shí yào chōng mǎn biàn de， hǎo xiàng shuǐ chōng mǎn yáng hǎi yī bān."],[2,15,"給人 酒喝、又加上毒物、 使他喝醉、好看見他下體的有禍了！","gěi rén jiǔ hē, yòu jiā shàng dú wù, shǐ tā hē zuì, hǎo kàn jiàn tā xià tǐ de yǒu huò le！"],[2,16,"你滿受羞辱，不得榮耀； 你也喝吧，顯出是未受割禮的！ 耶和華右手的杯必傳到你那裏； 你的榮耀就變為大大地羞辱。","nǐ mǎn shòu xiū rǔ， bù dé róng yào； nǐ yě hē ba， xiǎn chū shì wèi shòu gē lǐ de！ yé hé huá yòu shǒu de bēi bì chuán dào nǐ nà lǐ； nǐ de róng yào jiù biàn wèi dà dà de xiū rǔ."],[2,17,"你向 黎巴嫩行強暴與殘害 驚嚇野獸的事必遮蓋你； 因你殺人流血， 向國內的城並城中一切居民施行強暴。","nǐ xiàng lí bā nèn xíng qiáng bào yǔ cán hài jīng xià yě shòu de shì bì zhē gài nǐ； yīn nǐ shā rén liú xuè， xiàng guó nèi de chéng bìng chéng zhōng yī qiè jū mín shī xíng qiáng bào."],[2,18,"雕刻的偶像，人將它刻出來， 有甚麼益處呢？ 鑄造的偶像就是虛謊的師傅。 製造者倚靠這啞巴偶像有甚麼益處呢？","diāo kè de ǒu xiàng， rén jiāng tā kè chū lái， yǒu shèn me yì chù ne？ zhù zào de ǒu xiàng jiù shì xū huǎng de shī fù. zhì zào zhě yǐ kào zhè yǎ bā ǒu xiàng yǒu shèn me yì chù ne？"],[2,19,"對木偶說：醒起！ 對啞巴石像說：起來！那人有禍了！ 這個還能教訓人嗎？ 看哪，是包裹金銀的，其中毫無氣息。","duì mù ǒu shuō： xǐng qǐ！ duì yǎ bā shí xiàng shuō： qǐ lái！ nà rén yǒu huò le！ zhè gè hái néng jiào xùn rén ma？ kàn nǎ， shì bāo guǒ jīn yín de， qí zhōng háo wú qì xī."],[2,20,"惟耶和華在他的聖殿中； 全地的人都當在他面前肅敬靜默。","wéi yé hé huá zài tā de shèng diàn zhōng； quán de de rén dōu dāng zài tā miàn qián sù jìng jìng mò."],[3,1,"先知 哈巴谷的禱告，調用流離歌。","xiān zhī hā bā gǔ de dǎo gào， diào yòng liú lí gē."],[3,2,"耶和華啊，我聽見你的名聲就懼怕。 耶和華啊，求你在這些年間復興你的作為， 在這些年間顯明出來； 在發怒的時候以憐憫為念。","yé hé huá a， wǒ tīng jiàn nǐ de míng shēng jiù jù pà. yé hé huá a， qiú nǐ zài zhè xiē nián jiān fù xìng nǐ de zuò wèi， zài zhè xiē nián jiān xiǎn míng chū lái； zài fā nù de shí hòu yǐ lián mǐn wèi niàn."],[3,3,"神從 提幔而來； 聖者從 巴蘭山臨到。（細拉） 他的榮光遮蔽諸天； 頌讚充滿大地。","shén cóng tí màn ér lái； shèng zhě cóng bā lán shān lín dào.（xì lā） tā de róng guāng zhē bì zhū tiān； sòng zàn chōng mǎn dà de."],[3,4,"他的輝煌如同日光； 從他手裏 射出光線， 在其中藏着他的能力。","tā de huī huáng rú tóng rì guāng； cóng tā shǒu lǐ shè chū guāng xiàn， zài qí zhōng cáng zhe tā de néng lì."],[3,5,"在他前面有瘟疫流行； 在他腳下有熱症發出。","zài tā qián miàn yǒu wēn yì liú xíng； zài tā jiǎo xià yǒu rè zhèng fā chū."],[3,6,"他站立，量了大地， 觀看，趕散萬民。 永久的山崩裂； 長存的嶺塌陷； 他的作為與古時一樣。","tā zhàn lì， liàng le dà de， guān kàn， gǎn sàn wàn mín. yǒng jiǔ de shān bēng liè； zhǎng cún de lǐng tā xiàn； tā de zuò wèi yǔ gǔ shí yī yàng."],[3,7,"我見 古珊的帳棚遭難， 米甸的幔子戰兢。","wǒ jiàn gǔ shān de zhàng péng zāo nán， mǐ diàn de màn zǐ zhàn jīng."],[3,8,"耶和華啊，你乘在馬上， 坐在得勝的車上， 豈是不喜悅江河、 向江河發怒氣、 向洋海發憤恨嗎？","yé hé huá a， nǐ chéng zài mǎ shàng， zuò zài dé shèng de chē shàng， qǐ shì bù xǐ yuè jiāng hé, xiàng jiāng hé fā nù qì, xiàng yáng hǎi fā fèn hèn ma？"],[3,9,"你的弓全然顯露， 向眾支派所起的誓都是 可信的。（細拉） 你以江河分開大地。","nǐ de gōng quán rán xiǎn lù， xiàng zhòng zhī pài suǒ qǐ de shì dōu shì kě xìn de.（xì lā） nǐ yǐ jiāng hé fēn kāi dà de."],[3,10,"山嶺見你，無不戰懼； 大水氾濫過去， 深淵發聲，洶湧翻騰。","shān lǐng jiàn nǐ， wú bù zhàn jù； dà shuǐ fán làn guò qù， shēn yuān fā shēng， xiōng yǒng fān téng."],[3,11,"因你的箭射出發光， 你的槍閃出光耀， 日月都在本宮停住。","yīn nǐ de jiàn shè chū fā guāng， nǐ de qiāng shǎn chū guāng yào， rì yuè dōu zài běn gōng tíng zhù."],[3,12,"你發忿恨通行大地， 發怒氣責打列國，如同打糧。","nǐ fā fèn hèn tōng xíng dà de， fā nù qì zé dǎ liè guó， rú tóng dǎ liáng."],[3,13,"你出來要拯救你的百姓， 拯救你的受膏者， 打破惡人家長的頭， 露出他的腳，直到頸項。（細拉）","nǐ chū lái yào zhěng jiù nǐ de bǎi xìng， zhěng jiù nǐ de shòu gāo zhě， dǎ pò è rén jiā zhǎng de tóu， lù chū tā de jiǎo， zhí dào jǐng xiàng.（xì lā）"],[3,14,"你用 敵人的戈矛刺透他戰士的頭； 他們來如旋風，要將我們分散。 他們所喜愛的是暗中吞吃貧民。","nǐ yòng dí rén de gē máo cì tòu tā zhàn shì de tóu； tā men lái rú xuán fēng， yào jiāng wǒ men fēn sàn. tā men suǒ xǐ ài de shì àn zhōng tūn chī pín mín."],[3,15,"你乘馬踐踏 紅海， 就是踐踏洶湧的大水。","nǐ chéng mǎ jiàn tà hóng hǎi， jiù shì jiàn tà xiōng yǒng de dà shuǐ."],[3,16,"我聽見 耶和華的聲音， 身體戰兢，嘴唇發顫， 骨中朽爛； 我在所立之處戰兢。 我只可安靜等候災難之日臨到， 犯境之民上來。","wǒ tīng jiàn yé hé huá de shēng yīn， shēn tǐ zhàn jīng， zuǐ chún fā chàn， gǔ zhōng xiǔ làn； wǒ zài suǒ lì zhī chù zhàn jīng. wǒ zhǐ kě ān jìng děng hòu zāi nán zhī rì lín dào， fàn jìng zhī mín shàng lái."],[3,17,"雖然無花果樹不發旺， 葡萄樹不結果， 橄欖樹也不效力， 田地不出糧食， 圈中絕了羊， 棚內也沒有牛；","suī rán wú huā guǒ shù bù fā wàng， pú táo shù bù jié guǒ， gǎn lǎn shù yě bù xiào lì， tián de bù chū liáng shí， quān zhōng jué le yáng， péng nèi yě méi yǒu niú；"],[3,18,"然而，我要因耶和華歡欣， 因救我的神喜樂。","rán ér， wǒ yào yīn yé hé huá huān xīn， yīn jiù wǒ de shén xǐ lè."],[3,19,"主耶和華是我的力量； 他使我的腳快如母鹿的 蹄， 又使我穩行在高處。 這歌交與伶長，用絲弦的樂器。","zhǔ yé hé huá shì wǒ de lì liàng； tā shǐ wǒ de jiǎo kuài rú mǔ lù de tí， yòu shǐ wǒ wěn xíng zài gāo chù. zhè gē jiāo yǔ líng zhǎng， yòng sī xián de lè qì."]],"arb-vandyck":[[1,1,"اَلْوَحْيُ ٱلَّذِي رَآهُ حَبَقُّوقُ ٱلنَّبِيُّ.","ạal̊waḥ̊yu ٱlãdẖī rā̂hu ḥabaqũwqu ٱlnãbīũ."],[1,2,"حَتَّى مَتَى يَارَبُّ أَدْعُو وَأَنْتَ لَا تَسْمَعُ؟ أَصْرُخُ إِلَيْكَ مِنَ ٱلظُّلْمِ وَأَنْتَ لَا تُخَلِّصُ؟","ḥatãy̱ matay̱ yārabũ ạảd̊ʿū wāản̊ta lā tas̊maʿu? ạảṣ̊rukẖu ại̹laẙka mina ٱlẓũl̊mi wāản̊ta lā tukẖalĩṣu?"],[1,3,"لِمَ تُرِينِي إِثْمًا، وَتُبْصِرُ جَوْرًا؟ وَقُدَّامِي ٱغْتِصَابٌ وَظُلْمٌ وَيَحْدُثُ خِصَامٌ وَتَرْفَعُ ٱلْمُخَاصَمَةُ نَفْسَهَا.","lima turīnī ại̹tẖ̊maⁿạ, watub̊ṣiru jaẘraⁿạ? waqudãạmī ٱgẖ̊tiṣābuⁿ waẓul̊muⁿ wayaḥ̊dutẖu kẖiṣāmuⁿ watar̊faʿu ٱl̊mukẖāṣamaẗu naf̊sahā."],[1,4,"لِذَلِكَ جَمَدَتِ ٱلشَّرِيعَةُ وَلَا يَخْرُجُ ٱلْحُكْمُ بَتَّةً، لِأَنَّ ٱلشِّرِّيرَ يُحِيطُ بِٱلصِّدِّيقِ، فَلِذَلِكَ يَخْرُجُ ٱلْحُكْمُ مُعْوَجًّا.","lidẖalika jamadati ٱlsẖãrīʿaẗu walā yakẖ̊ruju ٱl̊ḥuk̊mu batãẗaⁿ, liạảnã ٱlsẖĩrĩyra yuḥīṭu biٱlṣĩdĩyqi, falidẖalika yakẖ̊ruju ٱl̊ḥuk̊mu muʿ̊wajaⁿ̃ạ."],[1,5,"«اُنْظُرُوا بَيْنَ ٱلْأُمَمِ، وَأَبْصِرُوا وَتَحَيَّرُوا حَيْرَةً. لِأَنِّي عَامِلٌ عَمَلًا فِي أَيَّامِكُمْ لَا تُصَدِّقُونَ بِهِ إِنْ أُخْبِرَ بِهِ.","«ạun̊ẓurūạ baẙna ٱl̊ạủmami, wāảb̊ṣirūạ wataḥayãrūạ ḥaẙraẗaⁿ. liạảnĩy ʿāmiluⁿ ʿamalaⁿạ fī ạảyãạmikum̊ lā tuṣadĩqūna bihi ại̹n̊ ạủkẖ̊bira bihi."],[1,6,"فَهَأَنَذَا مُقِيمٌ ٱلْكَلْدَانِيِّينَ ٱلْأُمَّةَ ٱلْمُرَّةَ ٱلْقَاحِمَةَ ٱلسَّالِكَةَ فِي رِحَابِ ٱلْأَرْضِ لِتَمْلِكَ مَسَاكِنَ لَيْسَتْ لَهَا.","fahāảnadẖā muqīmuⁿ ٱl̊kal̊dānīĩyna ٱl̊ạủmãẗa ٱl̊murãẗa ٱl̊qāḥimaẗa ٱlsãạlikaẗa fī riḥābi ٱl̊ạảr̊ḍi litam̊lika masākina laẙsat̊ lahā."],[1,7,"هِيَ هَائِلَةٌ وَمَخُوفَةٌ. مِنْ قِبَلِ نَفْسِهَا يَخْرُجُ حُكْمُهَا وَجَلَالُهَا.","hīa hāyỉlaẗuⁿ wamakẖūfaẗuⁿ. min̊ qibali naf̊sihā yakẖ̊ruju ḥuk̊muhā wajalāluhā."],[1,8,"وَخَيْلُهَا أَسْرَعُ مِنَ ٱلنُّمُورِ، وَأَحَدُّ مِنْ ذِئَابِ ٱلْمَسَاءِ. وَفُرْسَانُهَا يَنْتَشِرُونَ، وَفُرْسَانُهَا يَأْتُونَ مِنْ بَعِيدٍ، وَيَطِيرُونَ كَٱلنَّسْرِ ٱلْمُسْرِعِ إِلَى ٱلْأَكْلِ.","wakẖaẙluhā ạảs̊raʿu mina ٱlnũmūri, wāảḥadũ min̊ dẖīảạbi ٱl̊masāʾi. wafur̊sānuhā yan̊tasẖirūna, wafur̊sānuhā yā̊̉tūna min̊ baʿīdiⁿ, wayaṭīrūna kaٱlnãs̊ri ٱl̊mus̊riʿi ại̹lay̱ ٱl̊ạảk̊li."],[1,9,"يَأْتُونَ كُلُّهُمْ لِلظُّلْمِ. مَنْظَرُ وُجُوهِهِمْ إِلَى قُدَّامٍ، وَيَجْمَعُونَ سَبْيًا كَٱلرَّمْلِ.","yā̊̉tūna kulũhum̊ lilẓũl̊mi. man̊ẓaru wujūhihim̊ ại̹lay̱ qudãạmiⁿ, wayaj̊maʿūna sab̊yaⁿạ kaٱlrãm̊li."],[1,10,"وَهِيَ تَسْخَرُ مِنَ ٱلْمُلُوكِ، وَٱلرُّؤَسَاءُ ضُحْكَةٌ لَهَا. وَتَضْحَكُ عَلَى كُلِّ حِصْنٍ، وَتُكَوِّمُ ٱلتُّرَابَ وَتَأْخُذُهُ.","wahīa tas̊kẖaru mina ٱl̊mulūki, waٱlrũwảsāʾu ḍuḥ̊kaẗuⁿ lahā. wataḍ̊ḥaku ʿalay̱ kulĩ ḥiṣ̊niⁿ, watukawĩmu ٱltũrāba watā̊̉kẖudẖuhu."],[1,11,"ثُمَّ تَتَعَدَّى رُوحُهَا فَتَعْبُرُ وَتَأْثَمُ. هَذِهِ قُوَّتُهَا إِلَهُهَا».","tẖumã tataʿadãy̱ rūḥuhā fataʿ̊buru watā̊̉tẖamu. hadẖihi qūãtuhā ại̹lahuhā»."],[1,12,"أَلَسْتَ أَنْتَ مُنْذُ ٱلْأَزَلِ يَارَبُّ إِلَهِي قُدُّوسِي؟ لَا نَمُوتُ. يَارَبُّ لِلْحُكْمِ جَعَلْتَهَا، وَيَا صَخْرُ لِلتَّأْدِيبِ أَسَّسْتَهَا.","ạảlas̊ta ạản̊ta mun̊dẖu ٱl̊ạảzali yārabũ ại̹lahī qudũwsī? lā namūtu. yārabũ lil̊ḥuk̊mi jaʿal̊tahā, wayā ṣakẖ̊ru liltãạ̊̉dībi ạảsãs̊tahā."],[1,13,"عَيْنَاكَ أَطْهَرُ مِنْ أَنْ تَنْظُرَا ٱلشَّرَّ، وَلَا تَسْتَطِيعُ ٱلنَّظَرَ إِلَى ٱلْجَوْرِ، فَلِمَ تَنْظُرُ إِلَى ٱلنَّاهِبِينَ، وَتَصْمُتُ حِينَ يَبْلَعُ ٱلشِّرِّيرُ مَنْ هُوَ أَبَرُّ مِنْهُ؟","ʿaẙnāka ạảṭ̊haru min̊ ạản̊ tan̊ẓurā ٱlsẖãrã, walā tas̊taṭīʿu ٱlnãẓara ại̹lay̱ ٱl̊jaẘri, falima tan̊ẓuru ại̹lay̱ ٱlnãạhibīna, wataṣ̊mutu ḥīna yab̊laʿu ٱlsẖĩrĩyru man̊ hūa ạảbarũ min̊hu?"],[1,14,"وَتَجْعَلُ ٱلنَّاسَ كَسَمَكِ ٱلْبَحْرِ، كَدَبَّابَاتٍ لَا سُلْطَانَ لَهَا.","wataj̊ʿalu ٱlnãạsa kasamaki ٱl̊baḥ̊ri, kadabãạbātiⁿ lā sul̊ṭāna lahā."],[1,15,"تُطْلِعُ ٱلْكُلَّ بِشِصِّهَا، وَتَصْطَادُهُمْ بِشَبَكَتِهَا وَتَجْمَعُهُمْ فِي مِصْيَدَتِهَا، فَلِذَلِكَ تَفْرَحُ وَتَبْتَهِجُ.","tuṭ̊liʿu ٱl̊kulã bisẖiṣĩhā, wataṣ̊ṭāduhum̊ bisẖabakatihā wataj̊maʿuhum̊ fī miṣ̊yadatihā, falidẖalika taf̊raḥu watab̊tahiju."],[1,16,"لِذَلِكَ تَذْبَحُ لِشَبَكَتِهَا، وَتُبَخِّرُ لِمِصْيَدَتِهَا، لِأَنَّهُ بِهِمَا سَمِنَ نَصِيبُهَا، وَطَعَامُهَا مُسَمَّنٌ.","lidẖalika tadẖ̊baḥu lisẖabakatihā, watubakẖĩru limiṣ̊yadatihā, liạảnãhu bihimā samina naṣībuhā, waṭaʿāmuhā musamãnuⁿ."],[1,17,"أَفَلِأَجْلِ هَذَا تَفْرَغُ شَبَكَتُهَا وَلَا تَعْفُو عَنْ قَتْلِ ٱلْأُمَمِ دَائِمًا؟","ạảfaliạảj̊li hadẖā taf̊ragẖu sẖabakatuhā walā taʿ̊fū ʿan̊ qat̊li ٱl̊ạủmami dāyỉmaⁿạ?"],[2,1,"عَلَى مَرْصَدِي أَقِفُ، وَعَلَى ٱلْحِصْنِ أَنْتَصِبُ، وَأُرَاقِبُ لِأَرَى مَاذَا يَقُولُ لِي، وَمَاذَا أُجِيبُ عَنْ شَكْوَايَ.","ʿalay̱ mar̊ṣadī ạảqifu, waʿalay̱ ٱl̊ḥiṣ̊ni ạản̊taṣibu, wāủrāqibu liạảray̱ mādẖā yaqūlu lī, wamādẖā ạủjību ʿan̊ sẖak̊wāya."],[2,2,"فَأَجَابَنِي ٱلرَّبُّ وَقَالَ: «ٱكْتُبِ ٱلرُّؤْيَا وَٱنْقُشْهَا عَلَى ٱلْأَلْوَاحِ لِكَيْ يَرْكُضَ قَارِئُهَا،","fāảjābanī ٱlrãbũ waqāla: «ٱk̊tubi ٱlrũẘ̉yā waٱn̊qusẖ̊hā ʿalay̱ ٱl̊ạảl̊wāḥi likaẙ yar̊kuḍa qārīủhā,"],[2,3,"لِأَنَّ ٱلرُّؤْيَا بَعْدُ إِلَى ٱلْمِيعَادِ، وَفِي ٱلنِّهَايَةِ تَتَكَلَّمُ وَلَا تَكْذِبُ. إِنْ تَوَانَتْ فَٱنْتَظِرْهَا لِأَنَّهَا سَتَأْتِي إِتْيَانًا وَلَا تَتَأَخَّرُ.","liạảnã ٱlrũẘ̉yā baʿ̊du ại̹lay̱ ٱl̊mīʿādi, wafī ٱlnĩhāyaẗi tatakalãmu walā tak̊dẖibu. ại̹n̊ tawānat̊ faٱn̊taẓir̊hā liạảnãhā satā̊̉tī ại̹t̊yānaⁿạ walā tatāảkẖãru."],[2,4,"«هُوَذَا مُنْتَفِخَةٌ غَيْرُ مُسْتَقِيمَةٍ نَفْسُهُ فِيهِ. وَٱلْبَارُّ بِإِيمَانِهِ يَحْيَا.","«hūadẖā mun̊tafikẖaẗuⁿ gẖaẙru mus̊taqīmaẗiⁿ naf̊suhu fīhi. waٱl̊bārũ biại̹ymānihi yaḥ̊yā."],[2,5,"وَحَقًّا إِنَّ ٱلْخَمْرَ غَادِرَةٌ. ٱلرَّجُلَ مُتَكَبِّرٌ وَلَا يَهْدَأُ. ٱلَّذِي قَدْ وَسَّعَ نَفْسَهُ كَٱلْهَاوِيَةِ، وَهُوَ كَٱلْمَوْتِ فَلَا يَشْبَعُ، بَلْ يَجْمَعُ إِلَى نَفْسِهِ كُلَّ ٱلْأُمَمِ، وَيَضُمُّ إِلَى نَفْسِهِ جَمِيعَ ٱلشُّعُوبِ.","waḥaqaⁿ̃ạ ại̹nã ٱl̊kẖam̊ra gẖādiraẗuⁿ. ٱlrãjula mutakabĩruⁿ walā yah̊dāủ. ٱlãdẖī qad̊ wasãʿa naf̊sahu kaٱl̊hāwīaẗi, wahūa kaٱl̊maẘti falā yasẖ̊baʿu, bal̊ yaj̊maʿu ại̹lay̱ naf̊sihi kulã ٱl̊ạủmami, wayaḍumũ ại̹lay̱ naf̊sihi jamīʿa ٱlsẖũʿūbi."],[2,6,"فَهَلَّا يَنْطِقُ هَؤُلَاءِ كُلُّهُمْ بِهَجْوٍ عَلَيْهِ وَلُغْزِ شَمَاتَةٍ بِهِ، وَيَقُولُونَ: وَيْلٌ لِلْمُكَثِّرِ مَا لَيْسَ لَهُ! إِلَى مَتَى؟ وَلِلْمُثَقِّلِ نَفْسَهُ رُهُونًا!","fahalãạ yan̊ṭiqu hawủlāʾi kulũhum̊ bihaj̊wiⁿ ʿalaẙhi walugẖ̊zi sẖamātaẗiⁿ bihi, wayaqūlūna: waẙluⁿ lil̊mukatẖĩri mā laẙsa lahu! ại̹lay̱ matay̱? walil̊mutẖaqĩli naf̊sahu ruhūnaⁿạ!"],[2,7,"أَلَا يَقُومُ بَغْتَةً مُقَارِضُوكَ، وَيَسْتَيْقِظُ مُزَعْزِعُوكَ، فَتَكُونَ غَنِيمَةً لَهُمْ؟","ạảlā yaqūmu bagẖ̊taẗaⁿ muqāriḍūka, wayas̊taẙqiẓu muzaʿ̊ziʿūka, fatakūna gẖanīmaẗaⁿ lahum̊?"],[2,8,"لِأَنَّكَ سَلَبْتَ أُمَمًا كَثِيرَةً، فَبَقِيَّةُ ٱلشُّعُوبِ كُلِّهَا تَسْلُبُكَ لِدِمَاءِ ٱلنَّاسِ وَظُلْمِ ٱلْأَرْضِ وَٱلْمَدِينَةِ وَجَمِيعِ ٱلسَّاكِنِينَ فِيهَا.","liạảnãka salab̊ta ạủmamaⁿạ katẖīraẗaⁿ, fabaqīãẗu ٱlsẖũʿūbi kulĩhā tas̊lubuka lidimāʾi ٱlnãạsi waẓul̊mi ٱl̊ạảr̊ḍi waٱl̊madīnaẗi wajamīʿi ٱlsãạkinīna fīhā."],[2,9,"«وَيْلٌ لِلْمُكْسِبِ بَيْتَهُ كَسْبًا شِرِّيرًا لِيَجْعَلَ عُشَّهُ فِي ٱلْعُلُوِّ لِيَنْجُوَ مِنْ كَفِّ ٱلشَّرِّ!","«waẙluⁿ lil̊muk̊sibi baẙtahu kas̊baⁿạ sẖirĩyraⁿạ līaj̊ʿala ʿusẖãhu fī ٱl̊ʿulūĩ līan̊jūa min̊ kafĩ ٱlsẖãrĩ!"],[2,10,"تَآمَرْتَ ٱلْخِزْيَ لِبَيْتِكَ. إِبَادَةَ شُعُوبٍ كَثِيرَةٍ وَأَنْتَ مُخْطِئٌ لِنَفْسِكَ.","tā̂mar̊ta ٱl̊kẖiz̊ya libaẙtika. ại̹bādaẗa sẖuʿūbiⁿ katẖīraẗiⁿ wāản̊ta mukẖ̊ṭīuⁿ̉ linaf̊sika."],[2,11,"لِأَنَّ ٱلْحَجَرَ يَصْرُخُ مِنَ ٱلْحَائِطِ فَيُجِيبُهُ ٱلْجَائِزُ مِنَ ٱلْخَشَبِ.","liạảnã ٱl̊ḥajara yaṣ̊rukẖu mina ٱl̊ḥāyỉṭi fayujībuhu ٱl̊jāyỉzu mina ٱl̊kẖasẖabi."],[2,12,"«وَيْلٌ لِلْبَانِي مَدِينَةً بِٱلدِّمَاءِ، وَلِلْمُؤَسِّسِ قَرْيَةً بِٱلْإِثْمِ!","«waẙluⁿ lil̊bānī madīnaẗaⁿ biٱldĩmāʾi, walil̊mūảsĩsi qar̊yaẗaⁿ biٱl̊ại̹tẖ̊mi!"],[2,13,"أَلَيْسَ مِنْ قِبَلِ رَبِّ ٱلْجُنُودِ أَنَّ ٱلشُّعُوبَ يَتْعَبُونَ لِلنَّارِ، وَٱلْأُمَمَ لِلْبَاطِلِ يَعْيَوْنَ؟","ạảlaẙsa min̊ qibali rabĩ ٱl̊junūdi ạảnã ٱlsẖũʿūba yat̊ʿabūna lilnãạri, waٱl̊ạủmama lil̊bāṭili yaʿ̊yaẘna?"],[2,14,"لِأَنَّ ٱلْأَرْضَ تَمْتَلِئُ مِنْ مَعْرِفَةِ مَجْدِ ٱلرَّبِّ كَمَا تُغَطِّي ٱلْمِيَاهُ ٱلْبَحْرَ.","liạảnã ٱl̊ạảr̊ḍa tam̊talīủ min̊ maʿ̊rifaẗi maj̊di ٱlrãbĩ kamā tugẖaṭĩy ٱl̊mīāhu ٱl̊baḥ̊ra."],[2,15,"«وَيْلٌ لِمَنْ يَسْقِي صَاحِبَهُ سَافِحًا حُمُوَّكَ وَمُسْكِرًا أَيْضًا، لِلنَّظَرِ إِلَى عَوْرَاتِهِمْ.","«waẙluⁿ liman̊ yas̊qī ṣāḥibahu sāfiḥaⁿạ ḥumūãka wamus̊kiraⁿạ ạảẙḍaⁿạ, lilnãẓari ại̹lay̱ ʿaẘrātihim̊."],[2,16,"قَدْ شَبِعْتَ خِزْيًا عِوَضًا عَنِ ٱلْمَجْدِ. فَٱشْرَبْ أَنْتَ أَيْضًا وَٱكْشِفْ غُرْلَتَكَ! تَدُورُ إِلَيْكَ كَأْسُ يَمِينِ ٱلرَّبِّ، وَقُيَاءُ ٱلْخِزْيِ عَلَى مَجْدِكَ.","qad̊ sẖabiʿ̊ta kẖiz̊yaⁿạ ʿiwaḍaⁿạ ʿani ٱl̊maj̊di. faٱsẖ̊rab̊ ạản̊ta ạảẙḍaⁿạ waٱk̊sẖif̊ gẖur̊lataka! tadūru ại̹laẙka kā̊̉su yamīni ٱlrãbĩ, waquyāʾu ٱl̊kẖiz̊yi ʿalay̱ maj̊dika."],[2,17,"لِأَنَّ ظُلْمَ لُبْنَانَ يُغَطِّيكَ، وَٱغْتِصَابَ ٱلْبَهَائِمِ ٱلَّذِي رَوَّعَهَا، لِأَجْلِ دِمَاءِ ٱلنَّاسِ وَظُلْمِ ٱلْأَرْضِ وَٱلْمَدِينَةِ وَجَمِيعِ ٱلسَّاكِنِينَ فِيهَا.","liạảnã ẓul̊ma lub̊nāna yugẖaṭĩyka, waٱgẖ̊tiṣāba ٱl̊bahāyỉmi ٱlãdẖī rawãʿahā, liạảj̊li dimāʾi ٱlnãạsi waẓul̊mi ٱl̊ạảr̊ḍi waٱl̊madīnaẗi wajamīʿi ٱlsãạkinīna fīhā."],[2,18,"«مَاذَا نَفَعَ ٱلتِّمْثَالُ ٱلْمَنْحُوتُ حَتَّى نَحَتَهُ صَانِعُهُ؟ أَوِ ٱلْمَسْبُوكُ وَمُعَلِّمُ ٱلْكَذِبِ حَتَّى إِنَّ ٱلصَّانِعَ صَنْعَةً يَتَّكِلُ عَلَيْهَا، فَيَصْنَعُ أَوْثَانًا بُكْمًا؟","«mādẖā nafaʿa ٱltĩm̊tẖālu ٱl̊man̊ḥūtu ḥatãy̱ naḥatahu ṣāniʿuhu? ạảwi ٱl̊mas̊būku wamuʿalĩmu ٱl̊kadẖibi ḥatãy̱ ại̹nã ٱlṣãạniʿa ṣan̊ʿaẗaⁿ yatãkilu ʿalaẙhā, fayaṣ̊naʿu ạảẘtẖānaⁿạ buk̊maⁿạ?"],[2,19,"وَيْلٌ لِلْقَائِلِ لِلْعُودِ: ٱسْتَيْقِظْ! وَلِلْحَجَرِ ٱلْأَصَمِّ: ٱنْتَبِهْ! أَهُوَ يُعَلِّمُ؟ هَا هُوَ مَطْلِيٌّ بِٱلذَّهَبِ وَٱلْفِضَّةِ، وَلَا رُوحَ ٱلْبَتَّةَ فِي دَاخِلِهِ!","waẙluⁿ lil̊qāyỉli lil̊ʿūdi: ٱs̊taẙqiẓ̊! walil̊ḥajari ٱl̊ạảṣamĩ: ٱn̊tabih̊! ạảhūa yuʿalĩmu? hā hūa maṭ̊līuⁿ̃ biٱldẖãhabi waٱl̊fiḍãẗi, walā rūḥa ٱl̊batãẗa fī dākẖilihi!"],[2,20,"أَمَّا ٱلرَّبُّ فَفِي هَيْكَلِ قُدْسِهِ. فَٱسْكُتِي قُدَّامَهُ يَا كُلَّ ٱلْأَرْضِ».","ạảmãạ ٱlrãbũ fafī haẙkali qud̊sihi. faٱs̊kutī qudãạmahu yā kulã ٱl̊ạảr̊ḍi»."],[3,1,"صَلَاةٌ لِحَبَقُّوقَ ٱلنَّبِيِّ عَلَى ٱلشَّجَوِيَّةِ:","ṣalāẗuⁿ liḥabaqũwqa ٱlnãbīĩ ʿalay̱ ٱlsẖãjawīãẗi:"],[3,2,"يَارَبُّ، قَدْ سَمِعْتُ خَبَرَكَ فَجَزِعْتُ. يَارَبُّ، عَمَلَكَ فِي وَسَطِ ٱلسِّنِينَ أَحْيِهِ. فِي وَسَطِ ٱلسِّنِينَ عَرِّفْ. فِي ٱلْغَضَبِ ٱذْكُرِ ٱلرَّحْمَةَ.","yārabũ, qad̊ samiʿ̊tu kẖabaraka fajaziʿ̊tu. yārabũ, ʿamalaka fī wasaṭi ٱlsĩnīna ạảḥ̊yihi. fī wasaṭi ٱlsĩnīna ʿarĩf̊. fī ٱl̊gẖaḍabi ٱdẖ̊kuri ٱlrãḥ̊maẗa."],[3,3,"ٱللهُ جَاءَ مِنْ تِيمَانَ، وَٱلْقُدُّوسُ مِنْ جَبَلِ فَارَانَ. سِلَاهْ. جَلَالُهُ غَطَّى ٱلسَّمَاوَاتِ، وَٱلْأَرْضُ ٱمْتَلَأَتْ مِنْ تَسْبِيحِهِ.","ٱllhu jāʾa min̊ tīmāna, waٱl̊qudũwsu min̊ jabali fārāna. silāh̊. jalāluhu gẖaṭãy̱ ٱlsãmāwāti, waٱl̊ạảr̊ḍu ٱm̊talāảt̊ min̊ tas̊bīḥihi."],[3,4,"وَكَانَ لَمَعَانٌ كَٱلنُّورِ. لَهُ مِنْ يَدِهِ شُعَاعٌ، وَهُنَاكَ ٱسْتِتَارُ قُدْرَتِهِ.","wakāna lamaʿānuⁿ kaٱlnũwri. lahu min̊ yadihi sẖuʿāʿuⁿ, wahunāka ٱs̊titāru qud̊ratihi."],[3,5,"قُدَّامَهُ ذَهَبَ ٱلْوَبَأُ، وَعِنْدَ رِجْلَيْهِ خَرَجَتِ ٱلْحُمَّى.","qudãạmahu dẖahaba ٱl̊wabāủ, waʿin̊da rij̊laẙhi kẖarajati ٱl̊ḥumãy̱."],[3,6,"وَقَفَ وَقَاسَ ٱلْأَرْضَ. نَظَرَ فَرَجَفَ ٱلْأُمَمُ وَدُكَّتِ ٱلْجِبَالُ ٱلدَّهْرِيَّةُ وَخَسَفَتْ آكَامُ ٱلْقِدَمِ. مَسَالِكُ ٱلْأَزَلِ لَهُ.","waqafa waqāsa ٱl̊ạảr̊ḍa. naẓara farajafa ٱl̊ạủmamu wadukãti ٱl̊jibālu ٱldãh̊rīãẗu wakẖasafat̊ ậkāmu ٱl̊qidami. masāliku ٱl̊ạảzali lahu."],[3,7,"رَأَيْتُ خِيَامَ كُوشَانَ تَحْتَ بَلِيَّةٍ. رَجَفَتْ شُقَقُ أَرْضِ مِدْيَانَ.","rāảẙtu kẖīāma kūsẖāna taḥ̊ta balīãẗiⁿ. rajafat̊ sẖuqaqu ạảr̊ḍi mid̊yāna."],[3,8,"هَلْ عَلَى ٱلْأَنْهَارِ حَمِيَ يَارَبُّ؟ هَلْ عَلَى ٱلْأَنْهَارِ غَضَبُكَ؟ أَوْ عَلَى ٱلْبَحْرِ سَخَطُكَ حَتَّى إِنَّكَ رَكِبْتَ خَيْلَكَ، مَرْكَبَاتِكَ مَرْكَبَاتِ ٱلْخَلَاصِ؟","hal̊ ʿalay̱ ٱl̊ạản̊hāri ḥamīa yārabũ? hal̊ ʿalay̱ ٱl̊ạản̊hāri gẖaḍabuka? ạảẘ ʿalay̱ ٱl̊baḥ̊ri sakẖaṭuka ḥatãy̱ ại̹nãka rakib̊ta kẖaẙlaka, mar̊kabātika mar̊kabāti ٱl̊kẖalāṣi?"],[3,9,"عُرِّيَتْ قَوْسُكَ تَعْرِيَةً. سُبَاعِيَّاتُ سِهَامٍ كَلِمَتُكَ. سِلَاهْ. شَقَّقْتَ ٱلْأَرْضَ أَنْهَارًا.","ʿurĩyat̊ qaẘsuka taʿ̊rīaẗaⁿ. subāʿīãạtu sihāmiⁿ kalimatuka. silāh̊. sẖaqãq̊ta ٱl̊ạảr̊ḍa ạản̊hāraⁿạ."],[3,10,"أَبْصَرَتْكَ فَفَزِعَتِ ٱلْجِبَالُ. سَيْلُ ٱلْمِيَاهِ طَمَا. أَعْطَتِ ٱللُّجَّةُ صَوْتَهَا. رَفَعَتْ يَدَيْهَا إِلَى ٱلْعَلَاءِ.","ạảb̊ṣarat̊ka fafaziʿati ٱl̊jibālu. saẙlu ٱl̊mīāhi ṭamā. ạảʿ̊ṭati ٱllũjãẗu ṣaẘtahā. rafaʿat̊ yadaẙhā ại̹lay̱ ٱl̊ʿalāʾi."],[3,11,"اَلشَّمْسُ وَٱلْقَمَرُ وَقَفَا فِي بُرُوجِهِمَا لِنُورِ سِهَامِكَ ٱلطَّائِرَةِ، لِلَمَعَانِ بَرْقِ مَجْدِكَ.","ạalsẖãm̊su waٱl̊qamaru waqafā fī burūjihimā linūri sihāmika ٱlṭãạyỉraẗi, lilamaʿāni bar̊qi maj̊dika."],[3,12,"بِغَضَبٍ خَطَرْتَ فِي ٱلْأَرْضِ، بِسَخَطٍ دُسْتَ ٱلْأُمَمَ.","bigẖaḍabiⁿ kẖaṭar̊ta fī ٱl̊ạảr̊ḍi, bisakẖaṭiⁿ dus̊ta ٱl̊ạủmama."],[3,13,"خَرَجْتَ لِخَلَاصِ شَعْبِكَ، لِخَلَاصِ مَسِيحِكَ. سَحَقْتَ رَأْسَ بَيْتِ ٱلشِّرِّيرِ مُعَرِّيًا ٱلْأَسَاسَ حَتَّى ٱلْعُنُقِ. سِلَاهْ.","kẖaraj̊ta likẖalāṣi sẖaʿ̊bika, likẖalāṣi masīḥika. saḥaq̊ta rā̊̉sa baẙti ٱlsẖĩrĩyri muʿarĩyaⁿạ ٱl̊ạảsāsa ḥatãy̱ ٱl̊ʿunuqi. silāh̊."],[3,14,"ثَقَبْتَ بِسِهَامِهِ رَأْسَ قَبَائِلِهِ. عَصَفُوا لِتَشْتِيتِي. ٱبْتِهَاجُهُمْ كَمَا لِأَكْلِ ٱلْمِسْكِينِ فِي ٱلْخُفْيَةِ.","tẖaqab̊ta bisihāmihi rā̊̉sa qabāyỉlihi. ʿaṣafūạ litasẖ̊tītī. ٱb̊tihājuhum̊ kamā liạảk̊li ٱl̊mis̊kīni fī ٱl̊kẖuf̊yaẗi."],[3,15,"سَلَكْتَ ٱلْبَحْرَ بِخَيْلِكَ، كُوَمَ ٱلْمِيَاهِ ٱلْكَثِيرَةِ.","salak̊ta ٱl̊baḥ̊ra bikẖaẙlika, kūama ٱl̊mīāhi ٱl̊katẖīraẗi."],[3,16,"سَمِعْتُ فَٱرْتَعَدَتْ أَحْشَائِي. مِنَ ٱلصَّوْتِ رَجَفَتْ شَفَتَايَ. دَخَلَ ٱلنَّخْرُ فِي عِظَامِي، وَٱرْتَعَدْتُ فِي مَكَانِي لِأَسْتَرِيحَ فِي يَوْمِ ٱلضِّيقِ، عِنْدَ صُعُودِ ٱلشَّعْبِ ٱلَّذِي يَزْحَمُنَا.","samiʿ̊tu faٱr̊taʿadat̊ ạảḥ̊sẖāyỉy. mina ٱlṣãẘti rajafat̊ sẖafatāya. dakẖala ٱlnãkẖ̊ru fī ʿiẓāmī, waٱr̊taʿad̊tu fī makānī liạảs̊tarīḥa fī yaẘmi ٱlḍĩyqi, ʿin̊da ṣuʿūdi ٱlsẖãʿ̊bi ٱlãdẖī yaz̊ḥamunā."],[3,17,"فَمَعَ أَنَّهُ لَا يُزْهِرُ ٱلتِّينُ، وَلَا يَكُونُ حَمْلٌ فِي ٱلْكُرُومِ. يَكْذِبُ عَمَلُ ٱلزَّيْتُونَةِ، وَٱلْحُقُولُ لَا تَصْنَعُ طَعَامًا. يَنْقَطِعُ ٱلْغَنَمُ مِنَ ٱلْحَظِيرَةِ، وَلَا بَقَرَ فِي ٱلْمَذَاوِدِ،","famaʿa ạảnãhu lā yuz̊hiru ٱltĩynu, walā yakūnu ḥam̊luⁿ fī ٱl̊kurūmi. yak̊dẖibu ʿamalu ٱlzãẙtūnaẗi, waٱl̊ḥuqūlu lā taṣ̊naʿu ṭaʿāmaⁿạ. yan̊qaṭiʿu ٱl̊gẖanamu mina ٱl̊ḥaẓīraẗi, walā baqara fī ٱl̊madẖāwidi,"],[3,18,"فَإِنِّي أَبْتَهِجُ بِٱلرَّبِّ وَأَفْرَحُ بِإِلَهِ خَلَاصِي.","fāi̹nĩy ạảb̊tahiju biٱlrãbĩ wāảf̊raḥu biại̹lahi kẖalāṣī."],[3,19,"اَلرَّبُّ ٱلسَّيِّدُ قُوَّتِي، وَيَجْعَلُ قَدَمَيَّ كَٱلْأَيَائِلِ، وَيُمَشِّينِي عَلَى مُرْتَفَعَاتِي. لِرَئِيسِ ٱلْمُغَنِّينَ عَلَى آلَاتِي ذَوَاتِ ٱلْأَوْتَارِ.","ạalrãbũ ٱlsãyĩdu qūãtī, wayaj̊ʿalu qadamayã kaٱl̊ạảyāyỉli, wayumasẖĩynī ʿalay̱ mur̊tafaʿātī. lirayỉysi ٱl̊mugẖanĩyna ʿalay̱ ậlātī dẖawāti ٱl̊ạảẘtāri."]],"bis-obbr":[[1,1,"Ol tok we i stap long buk ya, Hae God i soemaot long Profet Habakuk long wan vison*, blong hem i talemaot.","Ol tok we i stap long buk ya, Hae God i soemaot long Profet Habakuk long wan vison*, blong hem i talemaot."],[1,2,"Nao Profet Habakuk i talem se, “Hae God. Naoia, long ples blong mifala, ol man oli stap faet, oli stap kilkilim olgeta oli ded. Oltaem, mi stap krae i kam long yu blong yu givhan long mifala. ?Be wetaem bambae yu harem mi, yu tekemaot mifala long ol trabol ya?","Nao Profet Habakuk i talem se, “Hae God. Naoia, long ples blong mifala, ol man oli stap faet, oli stap kilkilim olgeta oli ded. Oltaem, mi stap krae i kam long yu blong yu givhan long mifala. ?Be wetaem bambae yu harem mi, yu tekemaot mifala long ol trabol ya?"],[1,3,"?From wanem yu letem mi mi stap luk ol trabol ya olsem? ?Bambae yu yu stap lukluk ol trabol ya gogo kasem wetaem? Naoia raonabaot long mi, ol man oli stap faet oli stap kilkilim olgeta, mo oli stap spolem olgeta samting. Olbaot long evri ples, ol man oli stap rao, mo oli stap faet.","?From wanem yu letem mi mi stap luk ol trabol ya olsem? ?Bambae yu yu stap lukluk ol trabol ya gogo kasem wetaem? Naoia raonabaot long mi, ol man oli stap faet oli stap kilkilim olgeta, mo oli stap spolem olgeta samting. Olbaot long evri ples, ol man oli stap rao, mo oli stap faet."],[1,4,"Long kot, ol jaj oli no moa stap folem loa, nao loa i no moa gat paoa. Ol man nogud oli stap tanem stret fasin i kam rabis fasin, nao oli stap winim ol stret man.”","Long kot, ol jaj oli no moa stap folem loa, nao loa i no moa gat paoa. Ol man nogud oli stap tanem stret fasin i kam rabis fasin, nao oli stap winim ol stret man.”"],[1,5,"Nao Profet Habakuk i talemaot we Hae God i talem se, “Ol man blong mi. Yufala i mas luklukgud long ol kantri ya we oli stap klosap long kantri blong yufala. Bambae yufala i sapraes long ol samting we bambae yufala i luk. Naoia long taem blong yufala, mi bambae mi mekem wan samting we taem yufala i harem nius blong hem, be bambae yufala i no save bilif nating.","Nao Profet Habakuk i talemaot we Hae God i talem se, “Ol man blong mi. Yufala i mas luklukgud long ol kantri ya we oli stap klosap long kantri blong yufala. Bambae yufala i sapraes long ol samting we bambae yufala i luk. Naoia long taem blong yufala, mi bambae mi mekem wan samting we taem yufala i harem nius blong hem, be bambae yufala i no save bilif nating."],[1,6,"Mi bambae mi letem long ol man Babilonia blong oli holem paoa. Ol man ya, fasin blong olgeta i strong tumas, mo oli no save stap kwaet. Oltaem, oli stap go long evri ples blong faet from graon we i no blong olgeta.","Mi bambae mi letem long ol man Babilonia blong oli holem paoa. Ol man ya, fasin blong olgeta i strong tumas, mo oli no save stap kwaet. Oltaem, oli stap go long evri ples blong faet from graon we i no blong olgeta."],[1,7,"Olgeta ya oli stap folem tingting blong olgeta nomo, mo oli flas tumas. Oltaem oli stap mekem olgeta man oli fraet we i fraet, we oli seksek tumas from.","Olgeta ya oli stap folem tingting blong olgeta nomo, mo oli flas tumas. Oltaem oli stap mekem olgeta man oli fraet we i fraet, we oli seksek tumas from."],[1,8,"“Ol hos blong olgeta, oli save spid we paoa blong olgeta i strong moa winim anamol ya leped*. Mo oli kros moa winim wael dog we i hanggri tumas, i wantem kakae. Oli stap skrasem graon, from we oli wantem hareap blong go. Ol man blong olgeta we oli stap ron long hos, oli aot longwe we longwe, oli stap resis i kam. Oli sut i kamdaon olsem bigfala pijin ya igel*, we i sut i kamdaon blong holem smol anamol blong i kakae.","“Ol hos blong olgeta, oli save spid we paoa blong olgeta i strong moa winim anamol ya leped*. Mo oli kros moa winim wael dog we i hanggri tumas, i wantem kakae. Oli stap skrasem graon, from we oli wantem hareap blong go. Ol man blong olgeta we oli stap ron long hos, oli aot longwe we longwe, oli stap resis i kam. Oli sut i kamdaon olsem bigfala pijin ya igel*, we i sut i kamdaon blong holem smol anamol blong i kakae."],[1,9,"“Taem ol soldia blong olgeta oli stap kam klosap blong faet agens long wan kantri, olgeta man oli fraet, oli stap seksek tumas from. Mo oltaem, ol man we ol enemi ya oli stap holem olgeta, blong oli go wok slef* blong olgeta, oli plante we plante olsem sanbij long solwota.","“Taem ol soldia blong olgeta oli stap kam klosap blong faet agens long wan kantri, olgeta man oli fraet, oli stap seksek tumas from. Mo oltaem, ol man we ol enemi ya oli stap holem olgeta, blong oli go wok slef* blong olgeta, oli plante we plante olsem sanbij long solwota."],[1,10,"Olgeta ya oli no save tinghevi long ol king blong ol kantri ya, mo oli stap laf long ol haeman blong ol king ya. I no gat wan taon nating we stonwol blong hem i naf blong blokem olgeta. Taem oli wantem go insaed long wan taon, oli stap hivimap graon i goraon long stonwol blong hem, nao oli klaem long hem, oli go insaed, oli holem taon ya.","Olgeta ya oli no save tinghevi long ol king blong ol kantri ya, mo oli stap laf long ol haeman blong ol king ya. I no gat wan taon nating we stonwol blong hem i naf blong blokem olgeta. Taem oli wantem go insaed long wan taon, oli stap hivimap graon i goraon long stonwol blong hem, nao oli klaem long hem, oli go insaed, oli holem taon ya."],[1,11,"Oli olsem hariken we i kam wantaem nomo i pas i go. Ol man nogud ya, oli stap trastem paoa blong olgeta nomo se i god blong olgeta.”","Oli olsem hariken we i kam wantaem nomo i pas i go. Ol man nogud ya, oli stap trastem paoa blong olgeta nomo se i god blong olgeta.”"],[1,12,"Nao Profet Habakuk i talem se, “Hae God. Yu yu God we yu stap bifo olgeta, mo yu yu God blong mi. Yu yu tabu, mo yu stap oltaem nomo, gogo i no save finis. Hae God, yu yu God blong mi, oltaem yu stap blokemgud mifala, blong mifala i no ded. Yu nomo yu letem blong ol man Babilonia oli holem paoa blong oli kam winim mifala, oli panisim mifala.","Nao Profet Habakuk i talem se, “Hae God. Yu yu God we yu stap bifo olgeta, mo yu yu God blong mi. Yu yu tabu, mo yu stap oltaem nomo, gogo i no save finis. Hae God, yu yu God blong mi, oltaem yu stap blokemgud mifala, blong mifala i no ded. Yu nomo yu letem blong ol man Babilonia oli holem paoa blong oli kam winim mifala, oli panisim mifala."],[1,13,"Yu yu tabu we yu tabu. Yu no wantem nating blong luk ol rabis fasin, mo ol samting nogud we ol man oli stap mekem, oli no stret nating long ae blong yu. Be ol man Babilonia ya oli nogud we i nogud, man i no save trastem olgeta nating. ?From wanem yu stap lukluk nomo long olgeta, we yu no panisim olgeta? ?Taem oli stap kilim ol man we fasin blong olgeta i stret lelebet, winim olgeta, be from wanem yu yu stap kwaet?","Yu yu tabu we yu tabu. Yu no wantem nating blong luk ol rabis fasin, mo ol samting nogud we ol man oli stap mekem, oli no stret nating long ae blong yu. Be ol man Babilonia ya oli nogud we i nogud, man i no save trastem olgeta nating. ?From wanem yu stap lukluk nomo long olgeta, we yu no panisim olgeta? ?Taem oli stap kilim ol man we fasin blong olgeta i stret lelebet, winim olgeta, be from wanem yu yu stap kwaet?"],[1,14,"“?From wanem yu stap mekem long ol man, olsem we oli fis no oli flae, we oli no gat lida blong i lidim olgeta?","“?From wanem yu stap mekem long ol man, olsem we oli fis no oli flae, we oli no gat lida blong i lidim olgeta?"],[1,15,"Ol man Babilonia oli stap kasem ol man long huk, olsem fis, mo oli stap pulum plante long net. Mo taem oli stap pulum olgeta i go, oli stap singsingaot, from we oli glad we i glad.","Ol man Babilonia oli stap kasem ol man long huk, olsem fis, mo oli stap pulum plante long net. Mo taem oli stap pulum olgeta i go, oli stap singsingaot, from we oli glad we i glad."],[1,16,"Net ya i olsem god blong olgeta, mo oli stap bonem insens* blong mekem wosip long hem, mo oli stap kilim anamol blong mekem sakrefaes long hem. Oli stap mekem olsem, from we oli luk se net ya i stap givhan long olgeta blong oli kasem plante gudgudfala samting.","Net ya i olsem god blong olgeta, mo oli stap bonem insens* blong mekem wosip long hem, mo oli stap kilim anamol blong mekem sakrefaes long hem. Oli stap mekem olsem, from we oli luk se net ya i stap givhan long olgeta blong oli kasem plante gudgudfala samting."],[1,17,"“?Bambae ol man ya oli stap faet agens long ol kantri ya blong flatemgud olgeta, gogo kasem wetaem? Oli no gat sore nating.”","“?Bambae ol man ya oli stap faet agens long ol kantri ya blong flatemgud olgeta, gogo kasem wetaem? Oli no gat sore nating.”"],[2,1,"Nao Profet Habakuk i talem se, “Mi bambae mi klaem long wajhaos* blong mi, nao mi stap wet long Hae God, blong hem i talemaot samting we bambae mi go talem long ol man. Mo bambae mi stap wet tu long ol ansa blong ol tok blong mi we hem bambae i givim.","Nao Profet Habakuk i talem se, “Mi bambae mi klaem long wajhaos* blong mi, nao mi stap wet long Hae God, blong hem i talemaot samting we bambae mi go talem long ol man. Mo bambae mi stap wet tu long ol ansa blong ol tok blong mi we hem bambae i givim."],[2,2,"“Nao Hae God i givim ansa ya long mi, i talem se, ‘Habakuk. Ol samting ya we mi mi soemaot long yu long vison*, yu mas raetemdaon ol toktok blong hem long ol flat ston. Mo taem yu raetem ol tok blong hem, oli mas klia blong man i save ridim,","“Nao Hae God i givim ansa ya long mi, i talem se, ‘Habakuk. Ol samting ya we mi mi soemaot long yu long vison*, yu mas raetemdaon ol toktok blong hem long ol flat ston. Mo taem yu raetem ol tok blong hem, oli mas klia blong man i save ridim,"],[2,3,"from we taem blong ol samting ya i no kam yet, be bambae oli mas kamtru i no longtaem. Olgeta samting we mi mi soemaot long yu long vison ya bambae oli mas olsem. Maet yu luk se i tektaem tumas blong kam, be bambae i mas kamtru long stret taem blong hem, mo yu yu mas wet long hem.","from we taem blong ol samting ya i no kam yet, be bambae oli mas kamtru i no longtaem. Olgeta samting we mi mi soemaot long yu long vison ya bambae oli mas olsem. Maet yu luk se i tektaem tumas blong kam, be bambae i mas kamtru long stret taem blong hem, mo yu yu mas wet long hem."],[2,4,"Tok blong mi i olsem. Olgeta we oli stap mekem ol rabis fasin, bambae oli no save laef. Be olgeta ya nomo we fasin blong olgeta i stret, bambae oli save laef, from we tingting blong olgeta i stap strong long mi nomo.’ ”","Tok blong mi i olsem. Olgeta we oli stap mekem ol rabis fasin, bambae oli no save laef. Be olgeta ya nomo we fasin blong olgeta i stret, bambae oli save laef, from we tingting blong olgeta i stap strong long mi nomo.’ ”"],[2,5,"Nao Profet Habakuk i talem se, “Sipos man i gat plante gudgudfala samting, be ol samting ya oli save trikim hem nomo. Ol man we oli gat plante samting finis, be oltaem oli stap wantem blong kasem plante samting moa, mo oli praod, mo oli no save stap kwaet. Oli olsem Hom* blong ol Dedman, we neva i save talem se, ‘I naf ya.’ From samting ya, oli stap faet agens long ol narafala kantri, oli stap winim olgeta, blong oli holem i blong olgeta.","Nao Profet Habakuk i talem se, “Sipos man i gat plante gudgudfala samting, be ol samting ya oli save trikim hem nomo. Ol man we oli gat plante samting finis, be oltaem oli stap wantem blong kasem plante samting moa, mo oli praod, mo oli no save stap kwaet. Oli olsem Hom* blong ol Dedman, we neva i save talem se, ‘I naf ya.’ From samting ya, oli stap faet agens long ol narafala kantri, oli stap winim olgeta, blong oli holem i blong olgeta."],[2,6,"Ol man blong olgeta kantri ya we ol man Babilonia ya oli winim olgeta, bambae oli ting rabis long olgeta, oli tok nogud long olgeta, oli talem se, ‘Hae God bambae i panisim yufala, from we yufala i stap tekem ol samting we i no blong yufala. Yufala i stap fosem ol man blong pemaot kaon blong olgeta long yufala long bigfala mane, blong mekem yufala i kam rijman. ?Be bambae yufala i lego fasin ya wetaem?’ ”","Ol man blong olgeta kantri ya we ol man Babilonia ya oli winim olgeta, bambae oli ting rabis long olgeta, oli tok nogud long olgeta, oli talem se, ‘Hae God bambae i panisim yufala, from we yufala i stap tekem ol samting we i no blong yufala. Yufala i stap fosem ol man blong pemaot kaon blong olgeta long yufala long bigfala mane, blong mekem yufala i kam rijman. ?Be bambae yufala i lego fasin ya wetaem?’ ”"],[2,7,"Nao profet i gohed i talem se, “Ol man nogud. Bambae yufala i sek we ol man ya we oli gat kaon long yufala bambae oli girap, oli faet agens long yufala, nao bambae yufala i fraet gud long olgeta we yufala i seksek from. Nao bambae oli tekemaot olgeta samting we yufala i gat, oli karem i blong olgeta.","Nao profet i gohed i talem se, “Ol man nogud. Bambae yufala i sek we ol man ya we oli gat kaon long yufala bambae oli girap, oli faet agens long yufala, nao bambae yufala i fraet gud long olgeta we yufala i seksek from. Nao bambae oli tekemaot olgeta samting we yufala i gat, oli karem i blong olgeta."],[2,8,"Bifo, yufala i stap kilim man i ded, mo yufala i stap mekem i nogud tumas long olgeta man long wol, mo long ol taon blong olgeta. Mo yufala i bin tekemaot olgeta samting blong plante man long plante kantri. Be naoia, olgeta we oli no ded, bambae oli kam tekemaot olgeta samting blong yufala, from fasin nogud ya blong yufala.","Bifo, yufala i stap kilim man i ded, mo yufala i stap mekem i nogud tumas long olgeta man long wol, mo long ol taon blong olgeta. Mo yufala i bin tekemaot olgeta samting blong plante man long plante kantri. Be naoia, olgeta we oli no ded, bambae oli kam tekemaot olgeta samting blong yufala, from fasin nogud ya blong yufala."],[2,9,"“Oltaem, yufala i stap mekem ol famle blong yufala oli kam rijman long fasin ya we yufala i stap fosem ol man, blong yufala i tekemaot olting blong olgeta. Mo yufala i stap yusum ol samting ya blong wokem ol gudgudfala hom blong yufala, we yufala i blokemgud olgeta, blong ol enemi oli no save kam spolem yufala. Nao from ol samting ya, Hae God bambae i panisim yufala.","“Oltaem, yufala i stap mekem ol famle blong yufala oli kam rijman long fasin ya we yufala i stap fosem ol man, blong yufala i tekemaot olting blong olgeta. Mo yufala i stap yusum ol samting ya blong wokem ol gudgudfala hom blong yufala, we yufala i blokemgud olgeta, blong ol enemi oli no save kam spolem yufala. Nao from ol samting ya, Hae God bambae i panisim yufala."],[2,10,"Be ol fasin ya blong yufala we yufala i mekem blong spolem ol narafala kantri, sem fasin ya nomo bambae i kasem yufala bakegen, mo i mekem bigfala sem long ol famle blong yufala.","Be ol fasin ya blong yufala we yufala i mekem blong spolem ol narafala kantri, sem fasin ya nomo bambae i kasem yufala bakegen, mo i mekem bigfala sem long ol famle blong yufala."],[2,11,"Ol stonwol nomo blong ol haos blong yufala, be bambae oli girap, oli talemaot ol poen agens long yufala bakegen. Mo ol rafta blong ol haos blong yufala tu, bambae oli talemaot sem samting ya bakegen.","Ol stonwol nomo blong ol haos blong yufala, be bambae oli girap, oli talemaot ol poen agens long yufala bakegen. Mo ol rafta blong ol haos blong yufala tu, bambae oli talemaot sem samting ya bakegen."],[2,12,"“Hae God bambae i panisim yufala, from we ol fasin nogud blong yufala i kam olsem fandesen blong taon blong yufala. Mo fasin ya blong kilim man i ded, i stap mekem taon blong yufala i kam bigwan moa.","“Hae God bambae i panisim yufala, from we ol fasin nogud blong yufala i kam olsem fandesen blong taon blong yufala. Mo fasin ya blong kilim man i ded, i stap mekem taon blong yufala i kam bigwan moa."],[2,13,"Ol kantri we yufala i winim olgeta, ol man blong hem oli stap hafded long ol wok blong yufala, we i blong nating nomo. Be ol wok ya blong olgeta, faea bambae i kakae olgeta evriwan. Hae God nomo i gat olgeta paoa, mo hem bambae i mekem ol samting ya i kamtru olsem.","Ol kantri we yufala i winim olgeta, ol man blong hem oli stap hafded long ol wok blong yufala, we i blong nating nomo. Be ol wok ya blong olgeta, faea bambae i kakae olgeta evriwan. Hae God nomo i gat olgeta paoa, mo hem bambae i mekem ol samting ya i kamtru olsem."],[2,14,"Long evri ples long wol, olgeta man bambae oli luksave bigfala paoa blong Hae God mo hae nem blong hem. Tingting ya bambae i kasem olgeta ples long wol, olsem solwota we i kavremap olgeta ples blong hem.","Long evri ples long wol, olgeta man bambae oli luksave bigfala paoa blong Hae God mo hae nem blong hem. Tingting ya bambae i kasem olgeta ples long wol, olsem solwota we i kavremap olgeta ples blong hem."],[2,15,"“Hae God bambae i panisim yufala, from we taem yufala i kros, yufala i stap mekem i nogud tumas long ol man we oli stap raonabaot long yufala. Yufala i daonem tingting blong olgeta, yufala i mekem olgeta oli sem tumas long fes blong ol narafala man. Yufala i mekem olgeta oli wokbaot olsem man we i drong.","“Hae God bambae i panisim yufala, from we taem yufala i kros, yufala i stap mekem i nogud tumas long ol man we oli stap raonabaot long yufala. Yufala i daonem tingting blong olgeta, yufala i mekem olgeta oli sem tumas long fes blong ol narafala man. Yufala i mekem olgeta oli wokbaot olsem man we i drong."],[2,16,"Be Hae God bambae i panisim yufala. Fasin ya we yufala i mekem long olgeta, bambae i kam kasem yufala bakegen. Bambae yufala i dring gogo yufala i drong we yufala i stap wokbaot neked nomo. Long taem ya, bambae ol man oli no moa save ona long yufala. Bambae oli mekem yufala i harem nogud, yufala i sem tumas long fes blong ol man.","Be Hae God bambae i panisim yufala. Fasin ya we yufala i mekem long olgeta, bambae i kam kasem yufala bakegen. Bambae yufala i dring gogo yufala i drong we yufala i stap wokbaot neked nomo. Long taem ya, bambae ol man oli no moa save ona long yufala. Bambae oli mekem yufala i harem nogud, yufala i sem tumas long fes blong ol man."],[2,17,"Yufala i katemdaon olgeta tri blong Lebanon finis. Long sem fasin Hae God bambae i katemdaon yufala evriwan. Mo ol anamol blong ples ya, yufala i kilim olgeta, be naoia, Hae God bambae i panisim yufala, i mekem yufala i fraet we i fraet. Samting ya bambae i kasem yufala from fasin nogud ya blong yufala, we yufala i stap kilim man i ded, mo from we yufala i stap mekem i nogud tumas long olgeta man long wol, mo long ol taon blong olgeta.","Yufala i katemdaon olgeta tri blong Lebanon finis. Long sem fasin Hae God bambae i katemdaon yufala evriwan. Mo ol anamol blong ples ya, yufala i kilim olgeta, be naoia, Hae God bambae i panisim yufala, i mekem yufala i fraet we i fraet. Samting ya bambae i kasem yufala from fasin nogud ya blong yufala, we yufala i stap kilim man i ded, mo from we yufala i stap mekem i nogud tumas long olgeta man long wol, mo long ol taon blong olgeta."],[2,18,"“Ol aedol blong yufala oli no god nating, oli blong giaman long yufala nomo, mo oli no save mekem wan samting. Man nomo i wokem olgeta long wud no long ston, mo oli no save toktok. !Man we i wokem aedol olsem, hem i stap trastem wan samting we hem nomo i wokem!","“Ol aedol blong yufala oli no god nating, oli blong giaman long yufala nomo, mo oli no save mekem wan samting. Man nomo i wokem olgeta long wud no long ston, mo oli no save toktok. !Man we i wokem aedol olsem, hem i stap trastem wan samting we hem nomo i wokem!"],[2,19,"Hae God bambae i panisim yufala, from we yufala i stap singaot long pis wud ya se, ‘!Yu wekap!’ no yufala i stap singaot long ston ya se, ‘!Yu girap!’ ?Weswe? ?Aedol ya i save soemaot sam samting long yufala? !Nogat! Maet yufala i blokem hem long silva no long gol blong flasem, be hem i no gat laef nating long hem.","Hae God bambae i panisim yufala, from we yufala i stap singaot long pis wud ya se, ‘!Yu wekap!’ no yufala i stap singaot long ston ya se, ‘!Yu girap!’ ?Weswe? ?Aedol ya i save soemaot sam samting long yufala? !Nogat! Maet yufala i blokem hem long silva no long gol blong flasem, be hem i no gat laef nating long hem."],[2,20,"“Be Hae God, hem i stap long tabu haos blong hem long heven. Mo olgeta man long wol oli mas stap kwaet long fes blong hem.”","“Be Hae God, hem i stap long tabu haos blong hem long heven. Mo olgeta man long wol oli mas stap kwaet long fes blong hem.”"],[3,1,"Nao Profet Habakuk i prea i talem se,","Nao Profet Habakuk i prea i talem se,"],[3,2,"“Hae God. Ol samting we yu yu bin mekem, mi mi harem nius blong hem finis, mo naoia mi ona long yu from we yu yu hae we yu hae. Mi wantem we naoia, long taem blong mifala, yu bambae yu mekem ol bigbigfala wok ya bakegen we yu bin mekem bifo. Yu yu kros long mifala, be plis yu sore long mifala bakegen.","“Hae God. Ol samting we yu yu bin mekem, mi mi harem nius blong hem finis, mo naoia mi ona long yu from we yu yu hae we yu hae. Mi wantem we naoia, long taem blong mifala, yu bambae yu mekem ol bigbigfala wok ya bakegen we yu bin mekem bifo. Yu yu kros long mifala, be plis yu sore long mifala bakegen."],[3,3,"“God, hem i tabu, hem i aot finis long hil ya Paran, i pas long Edom i stap kam. Bigfala laet we i soemaot paoa blong hem i stap saen raonabaot long hem, mo olgeta man long wol ya oli stap leftemap nem blong hem.","“God, hem i tabu, hem i aot finis long hil ya Paran, i pas long Edom i stap kam. Bigfala laet we i soemaot paoa blong hem i stap saen raonabaot long hem, mo olgeta man long wol ya oli stap leftemap nem blong hem."],[3,4,"Hem i aot long heven i stap kam, mo bigfala laet ya i stap saen raonabaot long hem. Laetning i stap saenaot long han blong hem, i soemaot we paoa i stap long han blong hem.","Hem i aot long heven i stap kam, mo bigfala laet ya i stap saen raonabaot long hem. Laetning i stap saenaot long han blong hem, i soemaot we paoa i stap long han blong hem."],[3,5,"Bigfala sik i go fastaem long hem, mo ded i stap kam biaen long hem.","Bigfala sik i go fastaem long hem, mo ded i stap kam biaen long hem."],[3,6,"Taem hem i no moa muv, wantaem nomo graon i seksek. Taem hem i lukluk i go long ol kantri, olgeta man oli fraet, oli seksek. Ol bigbigfala hil we oli stap bifo olgeta, oli brobrok long ol smosmol pis, oli folfoldaon. Mo ol smosmol hil we oli no save lus, oli draon. Olgeta hil ya, bifo, hem i stap pas long olgeta, be olgeta evriwan oli lus.","Taem hem i no moa muv, wantaem nomo graon i seksek. Taem hem i lukluk i go long ol kantri, olgeta man oli fraet, oli seksek. Ol bigbigfala hil we oli stap bifo olgeta, oli brobrok long ol smosmol pis, oli folfoldaon. Mo ol smosmol hil we oli no save lus, oli draon. Olgeta hil ya, bifo, hem i stap pas long olgeta, be olgeta evriwan oli lus."],[3,7,"Nao mi mi luk we ol man Kusan oli fraet, mo ol man Midian tu, oli fraet tumas oli seksek.","Nao mi mi luk we ol man Kusan oli fraet, mo ol man Midian tu, oli fraet tumas oli seksek."],[3,8,"“Hae God. ?Olsem wanem? ?Ol reva oli mekem yu yu kros? ?No solwota i mekem yu yu kros tumas? Taem yu yu kam blong givhan long ol man blong yu blong oli win, ol klaod oli olsem hos blong yu, mo hariken i olsem kat blong faet blong yu.","“Hae God. ?Olsem wanem? ?Ol reva oli mekem yu yu kros? ?No solwota i mekem yu yu kros tumas? Taem yu yu kam blong givhan long ol man blong yu blong oli win, ol klaod oli olsem hos blong yu, mo hariken i olsem kat blong faet blong yu."],[3,9,"Yu yu rere finis blong pulum bonara blong yu, we laetning i olsem ara blong yu we i spid i kam. Mo ol reva oli stap ron bigwan, oli brebrekem graon.","Yu yu rere finis blong pulum bonara blong yu, we laetning i olsem ara blong yu we i spid i kam. Mo ol reva oli stap ron bigwan, oli brebrekem graon."],[3,10,"Taem ol bigbigfala hil oli luk yu oli seksek tumas from. Bigfala ren i kam, nao ol reva oli ron bigwan. Mo ol wef blong solwota i stap go antap we antap, nao oli stap mekem bigfala noes.","Taem ol bigbigfala hil oli luk yu oli seksek tumas from. Bigfala ren i kam, nao ol reva oli ron bigwan. Mo ol wef blong solwota i stap go antap we antap, nao oli stap mekem bigfala noes."],[3,11,"Taem san mo mun tufala i luk laetning, we i olsem ol ara mo spia blong yu was but we need 1 line!! we oli spid i kam, tufala i stap kwaet, tufala i no moa muf.","Taem san mo mun tufala i luk laetning, we i olsem ol ara mo spia blong yu was but we need 1 line!! we oli spid i kam, tufala i stap kwaet, tufala i no moa muf."],[3,12,"Yu yu kros tumas long ol man blong olgeta kantri, nao yu maj i kam, yu stat long narasaed wol, yu gokros long narasaed, yu stap purumpurumbut long olgeta.","Yu yu kros tumas long ol man blong olgeta kantri, nao yu maj i kam, yu stat long narasaed wol, yu gokros long narasaed, yu stap purumpurumbut long olgeta."],[3,13,"“Yu yu go finis blong sevem ol man blong yu, wetem king blong olgeta we yu nomo yu makemaot. Man we i king blong ol man nogud, yu yu kilim hem finis, mo yu spolem olgeta man we oli biaen long hem.","“Yu yu go finis blong sevem ol man blong yu, wetem king blong olgeta we yu nomo yu makemaot. Man we i king blong ol man nogud, yu yu kilim hem finis, mo yu spolem olgeta man we oli biaen long hem."],[3,14,"Taem ol soldia blong hem oli kam olsem hariken blong spolem mifala, oli stap harem gud, olsem ol man we oli stap ravem ol puaman long fasin blong haed. Be long taem ya, ol ara blong yu oli kasemgud komanda blong ol soldia blong king ya.","Taem ol soldia blong hem oli kam olsem hariken blong spolem mifala, oli stap harem gud, olsem ol man we oli stap ravem ol puaman long fasin blong haed. Be long taem ya, ol ara blong yu oli kasemgud komanda blong ol soldia blong king ya."],[3,15,"Ol hos blong yu oli purumpurumbut long solwota, nao i mekem solwota i raf we i raf.","Ol hos blong yu oli purumpurumbut long solwota, nao i mekem solwota i raf we i raf."],[3,16,"“Taem mi mi harem nius blong ol samting ya, mi fraet we mi fraet, mi seksek tumas from, we fes blong mi i kam nogud, mo bodi blong mi i kam slak olgeta, mo leg blong mi i seksek tumas. “Be bambae mi mi stap wet gogo taem ya i kamtru, we olgeta ya we oli kam faet agens long mifala oli kasem panis.”","“Taem mi mi harem nius blong ol samting ya, mi fraet we mi fraet, mi seksek tumas from, we fes blong mi i kam nogud, mo bodi blong mi i kam slak olgeta, mo leg blong mi i seksek tumas. “Be bambae mi mi stap wet gogo taem ya i kamtru, we olgeta ya we oli kam faet agens long mifala oli kasem panis.”"],[3,17,"“Naoia yumi stap long trabol. Ol figtri* oli no moa karem kakae, mo ol grep* oli no moa karem frut blong wokem waen, mo ol tri ya olif* oli no moa karem frut blong wokem oel, mo i no moa gat kakae long ol garen, mo ol sipsip mo ol buluk oli ded evriwan.","“Naoia yumi stap long trabol. Ol figtri* oli no moa karem kakae, mo ol grep* oli no moa karem frut blong wokem waen, mo ol tri ya olif* oli no moa karem frut blong wokem oel, mo i no moa gat kakae long ol garen, mo ol sipsip mo ol buluk oli ded evriwan."],[3,18,"Be nating we ol trabol ya i kasem yumi olsem, mi bambae mi stap harem gud yet from we Hae God i God blong mi, mo hem i stap sevem mi.","Be nating we ol trabol ya i kasem yumi olsem, mi bambae mi stap harem gud yet from we Hae God i God blong mi, mo hem i stap sevem mi."],[3,19,"Hem nomo i stap givim paoa long mi, i stap mekem mi mi stanap strong olsem anamol ya dia*. Mo taem mi stap wokbaot antap long hil, hem i stap lukaot gud long mi.” Prea ya i blong sing wetem stringban.","Hem nomo i stap givim paoa long mi, i stap mekem mi mi stanap strong olsem anamol ya dia*. Mo taem mi stap wokbaot antap long hil, hem i stap lukaot gud long mi.” Prea ya i blong sing wetem stringban."]]}};